import React, { useMemo, useRef, useState } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { OrbitControls, Html, Line } from '@react-three/drei';
import * as THREE from 'three';

// 100% Accurate geographical node tracer based on the image mapped to a 350x350 grid
const regionsData = [
    {
        id: '176', name: 'BAGONG SILANG', number: '176', color: '#fde047', border: '#ca8a04', pos: [140, 50],
        pts: [[80, 30], [130, 20], [180, 30], [200, 50], [180, 90], [140, 95], [100, 80]]
    },

    {
        id: 'tala', name: 'TALA', number: '180-188', color: '#93c5fd', border: '#2563eb', pos: [240, 60],
        pts: [[200, 50], [230, 45], [280, 55], [285, 80], [260, 105], [220, 95], [180, 90]]
    },

    {
        id: '181', name: 'PANGARAP VILLAGE', number: '181-182', color: '#86efac', border: '#16a34a', pos: [310, 70],
        pts: [[280, 55], [330, 60], [340, 90], [320, 100], [285, 80]]
    },

    {
        id: 'camarin', name: 'CAMARIN', number: '174-178', color: '#fca5a5', border: '#dc2626', pos: [170, 130],
        pts: [[140, 95], [180, 90], [220, 95], [230, 160], [165, 155], [145, 135], [125, 120]]
    },

    {
        id: '179', name: 'AMPARO', number: '179', color: '#fdba74', border: '#ea580c', pos: [260, 140],
        pts: [[220, 95], [260, 105], [285, 80], [320, 100], [300, 165], [270, 185], [230, 160]]
    },

    {
        id: '171', name: 'BAGUMBONG', number: '171', color: '#86efac', border: '#16a34a', pos: [70, 110],
        pts: [[20, 130], [50, 100], [80, 30], [100, 80], [140, 95], [125, 120], [115, 160], [60, 165], [30, 150]]
    },

    {
        id: '173', name: 'CONGRESS', number: '173', color: '#93c5fd', border: '#2563eb', pos: [115, 140],
        pts: [[125, 120], [145, 135], [130, 170], [115, 160]]
    },

    {
        id: '172', name: 'URDUJA', number: '172', color: '#fdba74', border: '#ea580c', pos: [140, 160],
        pts: [[145, 135], [165, 155], [165, 185], [130, 170]]
    },

    {
        id: 'deparo', name: 'DEPARO', number: '168, 170', color: '#fde047', border: '#ca8a04', pos: [100, 185],
        pts: [[60, 165], [115, 160], [130, 170], [165, 185], [170, 200], [120, 205], [100, 195], [60, 190]]
    },

    {
        id: '169', name: 'BF HOMES', number: '169', color: '#fdba74', border: '#ea580c', pos: [130, 215],
        pts: [[100, 195], [120, 205], [130, 225], [120, 235], [95, 220]]
    },

    {
        id: '167', name: 'LLANO', number: '167', color: '#93c5fd', border: '#2563eb', pos: [80, 215],
        pts: [[60, 190], [100, 195], [95, 220], [120, 235], [110, 245], [75, 250], [50, 230]]
    },

    {
        id: '166', name: 'KAYBIGA', number: '166', color: '#fca5a5', border: '#dc2626', pos: [85, 270],
        pts: [[75, 250], [110, 245], [100, 290], [80, 310], [60, 280]]
    },

    {
        id: '165', name: 'BAGBAGUIN', number: '165', color: '#86efac', border: '#16a34a', pos: [45, 260],
        pts: [[50, 230], [75, 250], [60, 280], [35, 300], [25, 270], [30, 240]]
    }
];

// Reusable individual mesh component for each Barangay
const BarangayMesh = ({ data }) => {
    const [hovered, setHovered] = useState(false);
    const meshRef = useRef();

    // Create the exact interlocking polygon geometry
    const geometry = useMemo(() => {
        const shape = new THREE.Shape();
        shape.moveTo(data.pts[0][0], data.pts[0][1]);
        for (let i = 1; i < data.pts.length; i++) {
            shape.lineTo(data.pts[i][0], data.pts[i][1]);
        }
        shape.closePath();

        return new THREE.ExtrudeGeometry(shape, {
            depth: 10,
            bevelEnabled: true,
            bevelSegments: 2,
            steps: 1,
            bevelSize: 0.8,
            bevelThickness: 1.5
        });
    }, [data]);

    // Interactive elevation on mouse hover and subtle breathing effect
    useFrame((state, delta) => {
        if (meshRef.current) {
            // Elevate the Z-axis smoothly when hovered (Z acts as Up because of the group rotation)
            const targetZ = hovered ? -5 : 0;
            meshRef.current.position.z = THREE.MathUtils.lerp(meshRef.current.position.z, targetZ, 8 * delta);

            // Subtle breathing effect on opacity to give it life without harsh lights
            const time = state.clock.getElapsedTime();
            const material = meshRef.current.children[0]?.material;
            if (material) {
                const baseOpacity = hovered ? 0.95 : 0.85;
                const breathing = hovered ? 0 : Math.sin(time * 1.5 + data.pos[0]) * 0.03; // Less pulsating
                material.opacity = THREE.MathUtils.lerp(material.opacity, baseOpacity + breathing, 0.1);
            }
        }
    });

    return (
        <group>
            <mesh
                ref={meshRef}
                geometry={geometry}
                onPointerOver={(e) => { e.stopPropagation(); setHovered(true); document.body.style.cursor = 'pointer'; }}
                onPointerOut={() => { setHovered(false); document.body.style.cursor = 'auto'; }}
            >
                <meshStandardMaterial
                    color={data.color}
                    roughness={0.5}
                    metalness={0.1}
                    opacity={0.25}
                    transparent
                />
                <meshStandardMaterial
                    attach="material-1"
                    color={hovered ? '#ffffff' : data.border}
                    emissive={hovered ? data.border : '#000000'}
                    emissiveIntensity={hovered ? 0.3 : 0}
                />
            </mesh>

            {/* Floating interactive HTML label anchored to the geographical centroid */}
            <Html position={[data.pos[0], data.pos[1], hovered ? -15 : -5]} center distanceFactor={hovered ? 20 : 25} zIndexRange={[100, 0]}>
                <div
                    className={`flex flex-col items-center justify-center px-4 py-2 rounded-xl shadow-2xl transition-all duration-300 pointer-events-none ${hovered ? 'scale-110 shadow-orange-500/30' : 'scale-100 shadow-black/10'}`}
                    style={{
                        backgroundColor: `${data.color}F2`,
                        border: `2px solid ${data.border}`,
                        color: '#1e293b' // slate-800 for max contrast
                    }}
                >
                    <span className="font-display font-extrabold text-[15px] uppercase tracking-[0.15em] leading-none mb-1 text-black">
                        {data.name}
                    </span>
                    <span className="text-[12px] font-bold text-black opacity-80 leading-none">
                        {data.number}
                    </span>
                </div>
            </Html>
        </group>
    );
};

const SmartMapAssembly = () => {
    const groupRef = useRef();
    const pivotRef = useRef();

    useFrame((state) => {
        const t = state.clock.getElapsedTime();
        if (groupRef.current) {
            groupRef.current.position.y = -8 + Math.sin(t * 0.4) * 2; // Lower the baseline position
        }
        if (pivotRef.current) {
            pivotRef.current.rotation.z = t * 0.05; // Moderate rotation showcasing the whole map around its own center
        }
    });

    return (
        <group ref={groupRef} scale={[0.11, -0.11, 0.11]} rotation={[-Math.PI / 2.3, 0, 0]} position={[25, 0, -15]}>
            <group ref={pivotRef}>
                <group position={[-175, -150, 0]}>

            {/* 13 Geometrically accurate Extruded Barangays */}
            {regionsData.map((data, idx) => (
                <BarangayMesh key={data.id} data={data} />
            ))}

            {/* Simulated Glowing Utility Data Lines bridging the regions */}
            {[...Array(6)].map((_, i) => (
                <Line
                    key={`data-line-${i}`}
                    points={[
                        new THREE.Vector3(Math.random() * 300, Math.random() * 300, -12 - Math.random() * 10),
                        new THREE.Vector3(Math.random() * 300, Math.random() * 300, -12 - Math.random() * 10),
                        new THREE.Vector3(Math.random() * 300, Math.random() * 300, -12 - Math.random() * 10)
                    ]}
                    color="#f97316"
                    lineWidth={2.5}
                    opacity={0.4}
                    transparent
                />
            ))}

                </group>
            </group>
        </group>
    );
};

export default function HeroMap3D() {
    return (
        <div className="relative z-10" style={{ width: '100%', height: '100%', cursor: 'grab' }}>
            <Canvas camera={{ position: [0, 45, 45], fov: 40 }} gl={{ alpha: true }}>
                {/* Soft, even lighting without harsh 'sun-like' shadows */}
                <ambientLight intensity={1.8} />
                <directionalLight position={[0, 40, 10]} intensity={0.6} color="#ffffff" />

                <SmartMapAssembly />

                {/* Strictly controls view to be Top-Down Isometric */}
                <OrbitControls
                    enableZoom={false}
                    enablePan={false}
                    autoRotate={false}
                    maxPolarAngle={Math.PI / 2.2}
                    minPolarAngle={Math.PI / 6}
                    target={[0, 0, 0]}
                />
            </Canvas>
        </div>
    );
}

import React from 'react';
import { Shield, FileText, AlertCircle } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

/**
 * ComplianceReminder Component
 * 
 * Displays a professional LGU-branded compliance gateway for project phase transitions.
 * Correctly parses backend ValueErrors for Smart Gate enforcement based on RA 9184.
 */
const ComplianceReminder = ({ error, toTitleCase }) => {
    if (!error) return null;

    const isCompliance = typeof error === 'object' && error.type === 'COMPLIANCE';

    if (!isCompliance) {
        return (
            <motion.div 
                initial={{ opacity: 0, y: -10 }}
                animate={{ opacity: 1, y: 0 }}
                className="mb-3 p-3 bg-red-50 dark:bg-red-900/20 text-red-700 dark:text-red-300 border border-red-200 dark:border-red-800 rounded-xl text-xs font-bold flex items-start gap-2"
            >
                <AlertCircle size={14} className="shrink-0 mt-0.5 text-red-500" />
                <span>{typeof error === 'object' ? JSON.stringify(error) : error}</span>
            </motion.div>
        );
    }

    return (
        <motion.div 
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            className="mb-4 overflow-hidden rounded-2xl border border-amber-200 dark:border-amber-800/50 bg-white dark:bg-slate-900 shadow-xl shadow-amber-100/20 dark:shadow-none"
        >
            <div className="bg-amber-500 px-4 py-2 flex items-center justify-between">
                <div className="flex items-center gap-2 text-white">
                    <Shield size={16} className="animate-pulse" />
                    <span className="text-[11px] font-black uppercase tracking-tighter">RA 9184 Compliance Gateway</span>
                </div>
                <div className="px-2 py-0.5 bg-white/20 backdrop-blur-md rounded-lg text-[9px] font-black text-white uppercase tabular-nums tracking-widest">
                    {error.track}
                </div>
            </div>
            
            <div className="p-4 space-y-3">
                <div className="flex items-start gap-3">
                    <div className="w-8 h-8 rounded-full bg-amber-100 dark:bg-amber-900/30 flex items-center justify-center shrink-0 border border-amber-200 dark:border-amber-800/50">
                        <FileText size={14} className="text-amber-600 dark:text-amber-400" />
                    </div>
                    <div>
                        <h4 className="text-xs font-black text-slate-900 dark:text-white leading-tight">Missing Required Documentation</h4>
                        <p className="text-[10px] text-slate-500 mt-0.5">
                            The following documents are mandatory for the <span className="font-bold text-slate-700 dark:text-indigo-400">{error.phase}</span> phase transition under current track protocols.
                        </p>
                    </div>
                </div>
                
                <div className="grid grid-cols-1 gap-1.5 ml-11">
                    {error.missing?.map((doc, idx) => (
                        <div key={idx} className="flex items-center gap-2 group">
                            <div className="w-1.5 h-1.5 rounded-full bg-amber-400 shrink-0 group-hover:scale-125 transition-transform" />
                            <span className="text-xs font-bold text-slate-700 dark:text-slate-300">{toTitleCase(doc)}</span>
                        </div>
                    ))}
                </div>

                <div className="mt-2 bg-slate-50 dark:bg-slate-800/50 rounded-xl p-3 border border-slate-100 dark:border-slate-800 flex items-center gap-3">
                    <div className="w-1.5 h-8 bg-amber-400 rounded-full" />
                    <p className="text-[10px] text-slate-500 italic leading-relaxed">
                        "Strict adherence to procurement document requirements ensures audit integrity and prevents legal vacuums in government projects."
                    </p>
                </div>
            </div>
        </motion.div>
    );
};

export default ComplianceReminder;

import React, { useState, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { UploadCloud, File, FileText, CheckCircle, X, Loader2, ShieldCheck, AlertCircle } from 'lucide-react';

import { API_BASE_URL } from '../utils/apiBase';
const getToken = () => localStorage.getItem('pulso_token');

/** Convert raw FastAPI validation errors into a single readable reminder string */
function parseUploadError(raw) {
    try {
        const json = JSON.parse(raw);
        if (json?.detail && Array.isArray(json.detail)) {
            // FastAPI validation errors — pull out human-readable field names
            const missing = json.detail
                .filter(e => e.type === 'missing' || e.msg?.toLowerCase().includes('required'))
                .map(e => {
                    const field = e.loc?.[e.loc.length - 1] || 'unknown field';
                    const label = { target_model: 'Document Target Type', target_id: 'Linked Record ID', document_type: 'Document Type', file: 'File' }[field] || field;
                    return label;
                });
            if (missing.length) {
                return `Please ensure the following required fields are present before uploading: ${missing.join(', ')}.`;
            }
            // Generic FastAPI detail string
            if (typeof json.detail === 'string') return json.detail;
        }
        if (json?.detail) return String(json.detail);
    } catch (_) { /* not JSON */ }
    return raw || 'Upload failed. Please try again.';
}

export default function DocumentUploadModal({ targetModel, targetId, onClose, onUploadComplete }) {
    const [file, setFile] = useState(null);
    const [docType, setDocType] = useState('survey_report');
    const [isDragging, setIsDragging] = useState(false);
    const [uploading, setUploading] = useState(false);
    const [result, setResult] = useState(null); // { success: true/false, message: string, hash: string }
    const fileInputRef = useRef(null);

    const docTypes = [
        { value: 'survey_report', label: 'Survey Report' },
        { value: 'topo_map', label: 'Topographical Map' },
        { value: 'geotechnical_test', label: 'Geotechnical Test Report' },
        { value: 'prelim_survey', label: 'Preliminary Survey' },
        { value: 'design_plans', label: 'Design Plans (CAD/PDF)' },
        { value: 'detailed_estimate', label: 'Detailed Estimate' },
        { value: 's_curve', label: 'S-Curve Chart' },
        { value: 'abc', label: 'Approved Budget for Contract (ABC)' },
        { value: 'pow', label: 'Program of Works (POW)' },
        { value: 'itb', label: 'Invitation to Bid (ITB)' },
        { value: 'bac_resolution', label: 'BAC Resolution' },
        { value: 'contract', label: 'Contract Agreement' },
        { value: 'ntp', label: 'Notice to Proceed (NTP)' },
        { value: 'perf_bond', label: 'Performance Bond' },
        { value: 'car_insurance', label: 'CAR/CAS Insurance' },
        { value: 'job_order', label: 'Job Order' },
        { value: 'quotations_3', label: '3 Quotations (Fast Track)' },
        { value: 'final_photo', label: 'Final Completion Photo' },
        { value: 'completion_report', label: 'Completion Report' },
        { value: 'materials_test', label: 'Materials Test Results' },
        { value: 'as_built_plan', label: 'As-Built Plan' },
        { value: 'coa_inspection', label: 'COA Inspection Report' },
        { value: 'emergency_memo', label: 'Emergency Memorandum' },
        { value: 'fund_certification', label: 'Fund Certification' },
        { value: 'direct_negotiation_record', label: 'Direct Negotiation Record' },
        { value: 'emergency_pow', label: 'Emergency POW' },
    ];

    const handleFileChange = (e) => {
        if (e.target.files && e.target.files[0]) {
            setFile(e.target.files[0]);
            setResult(null);
        }
    };

    const handleDragOver = (e) => {
        e.preventDefault();
        setIsDragging(true);
    };

    const handleDragLeave = () => {
        setIsDragging(false);
    };

    const handleDrop = (e) => {
        e.preventDefault();
        setIsDragging(false);
        if (e.dataTransfer.files && e.dataTransfer.files[0]) {
            setFile(e.dataTransfer.files[0]);
            setResult(null);
        }
    };

    const handleUpload = async () => {
        if (!file) {
            alert("Please select a file first");
            return;
        }
        setUploading(true);
        setResult(null);

        const formData = new FormData();
        formData.append('file', file);
        formData.append('document_type', docType);
        formData.append('target_model', targetModel);
        formData.append('target_id', String(targetId));
        if (docType === 'materials_test') {
            formData.append('metadata_json', JSON.stringify({ compression_strength_pass: true }));
        }

        console.log("Uploading to:", `${API_BASE_URL}/api/gov/documents/upload`);
        console.log("Target:", targetModel, targetId, docType);
        console.log("Token exists:", !!getToken());

        try {
            const res = await fetch(`${API_BASE_URL}/api/gov/documents/upload`, {
                method: 'POST',
                headers: {
                    'Authorization': `Bearer ${getToken()}`
                },
                body: formData
            });
            
            console.log("Response status:", res.status);
            console.log("Response OK:", res.ok);
            console.log("Response status text:", res.statusText);
            
            if (!res.ok) {
                const text = await res.text();
                console.log("Error response text:", text);
                throw new Error(parseUploadError(text));
            }

            const data = await res.json();
            setResult({ success: true, message: 'Document secured and registered in the centralized repository.', hash: data.document?.sha256_hash || data.sha256_hash });
            if (onUploadComplete) onUploadComplete(data);
        } catch (error) {
            console.error("Upload error:", error);
            console.error("Error name:", error.name);
            console.error("Error message:", error.message);
            setResult({ success: false, message: error.message });
        } finally {
            setUploading(false);
        }
    };

    const handleClose = () => {
        if (uploading) {
            console.log("Cannot close modal while uploading");
            return;
        }
        console.log("Modal closing, result:", result);
        onClose();
    };

    // Prevent closing while uploading
    const handleBackdropClick = (e) => {
        if (!uploading) {
            onClose();
        }
    };

    return (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
            <motion.div 
                initial={{ opacity: 0 }} 
                animate={{ opacity: 1 }} 
                exit={{ opacity: 0 }}
                className="absolute inset-0 bg-slate-900/60" 
                onClick={handleBackdropClick}
            />
            
            <motion.div
                initial={{ opacity: 0, scale: 0.95, y: 20 }}
                animate={{ opacity: 1, scale: 1, y: 0 }}
                exit={{ opacity: 0, scale: 0.95, y: 20 }}
                className="relative w-full max-w-lg bg-white dark:bg-slate-900 rounded-3xl shadow-2xl border border-slate-200 dark:border-slate-800 overflow-hidden"
            >
                {/* Header */}
                <div className="px-6 py-4 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between bg-slate-50 dark:bg-slate-800">
                    <h3 className="text-lg font-black text-slate-900 dark:text-white flex items-center gap-2">
                        <UploadCloud className="text-indigo-600 dark:text-indigo-400" /> Secure Document Upload
                    </h3>
                    <button onClick={handleClose} className="p-2 text-slate-400 hover:text-slate-600 dark:hover:text-white rounded-full hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors">
                        <X size={20} />
                    </button>
                </div>

                <div className="p-6 space-y-6">
                    {!result?.success ? (
                        <>
                            {/* Document Type Selector */}
                            <div>
                                <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-2 uppercase tracking-wider">
                                    Document Designation
                                </label>
                                <select 
                                    value={docType}
                                    onChange={(e) => setDocType(e.target.value)}
                                    className="w-full bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-700 rounded-xl px-4 py-3 text-sm font-semibold text-slate-700 dark:text-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500"
                                >
                                    {docTypes.map(t => (
                                        <option key={t.value} value={t.value}>{t.label}</option>
                                    ))}
                                </select>
                            </div>

                            {/* Dropzone */}
                            <div 
                                className={`relative border-2 border-dashed rounded-2xl p-8 text-center transition-all ${isDragging ? 'border-indigo-500 bg-indigo-50/50 dark:bg-indigo-900/10' : 'border-slate-300 dark:border-slate-700 hover:border-slate-400 dark:hover:border-slate-600'}`}
                                onDragOver={handleDragOver}
                                onDragLeave={handleDragLeave}
                                onDrop={handleDrop}
                            >
                                <input 
                                    type="file" 
                                    ref={fileInputRef} 
                                    className="hidden" 
                                    onChange={handleFileChange}
                                    accept=".pdf,.png,.jpg,.jpeg,.gif,.bmp,.tiff,.tif,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.txt,.csv,.dwg,.dxf,.zip,.rar,.7z"
                                />
                                
                                <div className="flex flex-col items-center justify-center">
                                    <div className="w-16 h-16 rounded-2xl bg-indigo-100 dark:bg-indigo-900/30 flex items-center justify-center text-indigo-600 dark:text-indigo-400 mb-4 shadow-sm">
                                        <FileText size={32} />
                                    </div>
                                    {file ? (
                                        <div className="space-y-1">
                                            <p className="text-sm font-bold text-slate-900 dark:text-white truncate max-w-[250px]">{file.name}</p>
                                            <p className="text-xs text-slate-500">{(file.size / 1024 / 1024).toFixed(2)} MB</p>
                                            <button onClick={() => setFile(null)} className="text-xs text-red-500 hover:text-red-700 font-bold mt-2">Remove</button>
                                        </div>
                                    ) : (
                                        <>
                                            <p className="text-sm font-bold text-slate-700 dark:text-slate-300 mb-1">
                                                Drag and drop your document here
                                            </p>
                                            <p className="text-xs text-slate-500 mb-4">
                                                Supports PDF, CAD, JPG, PNG up to 50MB
                                            </p>
                                            <button 
                                                onClick={() => fileInputRef.current.click()}
                                                className="px-4 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm font-bold shadow-sm hover:shadow transition-all"
                                            >
                                                Browse Files
                                            </button>
                                        </>
                                    )}
                                </div>
                            </div>
                            
                            {result && !result.success && (
                                <div className="p-3 rounded-xl bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 flex items-start gap-3">
                                    <AlertCircle className="text-red-500 shrink-0 mt-0.5" size={16} />
                                    <p className="text-sm text-red-700 dark:text-red-300 text-left">{result.message}</p>
                                </div>
                            )}

                            <div className="flex gap-3 pt-2">
                                <button onClick={handleClose} className="flex-1 px-4 py-3 bg-slate-100/50 hover:bg-slate-200/50 dark:bg-slate-800/50 dark:hover:bg-slate-700/50 rounded-xl text-sm font-bold transition-colors">
                                    Cancel
                                </button>
                                <button 
                                    onClick={handleUpload}
                                    disabled={!file || uploading}
                                    className="flex-1 px-4 py-3 bg-indigo-600 hover:bg-indigo-700 disabled:bg-indigo-400 text-white rounded-xl text-sm font-bold shadow-lg shadow-indigo-200 dark:shadow-none transition-all flex items-center justify-center gap-2"
                                >
                                    {uploading ? <><Loader2 size={16} className="animate-spin" /> Securing...</> : 'Upload & Hash'}
                                </button>
                            </div>
                        </>
                    ) : (
                        <motion.div 
                            initial={{ scale: 0.9, opacity: 0 }}
                            animate={{ scale: 1, opacity: 1 }}
                            className="text-center py-6"
                        >
                            <div className="w-20 h-20 bg-emerald-100 dark:bg-emerald-900/40 rounded-full flex items-center justify-center mx-auto mb-6 text-emerald-500 shadow-xl shadow-emerald-100 dark:shadow-none">
                                <ShieldCheck size={40} />
                            </div>
                            <h4 className="text-xl font-black text-slate-900 dark:text-white mb-2">Upload Verified</h4>
                            <p className="text-sm text-slate-500 dark:text-slate-400 mb-6 px-4">
                                The document has been securely processed and bound to the central registry.
                            </p>
                            
                            <div className="text-left bg-slate-50 dark:bg-slate-950/50 rounded-xl p-4 border border-slate-200 dark:border-slate-800 mb-6">
                                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1">SHA-256 Fingerprint</p>
                                <p className="text-xs font-mono text-indigo-600 dark:text-indigo-400 break-all bg-white dark:bg-slate-900 p-2 rounded-lg border border-slate-100 dark:border-slate-800">
                                    {result.hash}
                                </p>
                            </div>

                            <button onClick={() => { onClose(); if(onUploadComplete) onUploadComplete(); }} className="w-full px-4 py-3 bg-slate-900 dark:bg-white text-white dark:text-slate-900 hover:bg-slate-800 dark:hover:bg-slate-100 rounded-xl text-sm font-bold transition-all">
                                Continue
                            </button>
                        </motion.div>
                    )}
                </div>
            </motion.div>
        </div>
    );
}

import React, { useRef, useState, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { X, RefreshCw, AlertCircle, CameraOff, MapPin } from 'lucide-react';

const IDCameraModal = ({ isOpen, onClose, onCapture, side = 'front', title, subtitle, metadata, guideText }) => {
    const videoRef = useRef(null);
    const canvasRef = useRef(null);
    const streamRef = useRef(null);
    const [error, setError] = useState(null);
    const [hasMultipleCameras, setHasMultipleCameras] = useState(false);
    const [facingMode, setFacingMode] = useState('environment');
    const [isLoading, setIsLoading] = useState(true);

    const stopStream = useCallback(() => {
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
            streamRef.current = null;
        }
        if (videoRef.current) {
            videoRef.current.srcObject = null;
        }
    }, []);

    const startStream = useCallback(async () => {
        setIsLoading(true);
        setError(null);
        stopStream();

        try {
            const constraints = {
                video: {
                    facingMode: facingMode,
                    width: { ideal: 1920 },
                    height: { ideal: 1080 }
                },
                audio: false
            };

            const newStream = await navigator.mediaDevices.getUserMedia(constraints);
            streamRef.current = newStream;

            if (videoRef.current) {
                videoRef.current.srcObject = newStream;
                await new Promise((resolve) => {
                    videoRef.current.onloadedmetadata = () => {
                        videoRef.current.play();
                        resolve();
                    };
                });
            }

            const devices = await navigator.mediaDevices.enumerateDevices();
            const videoDevices = devices.filter(d => d.kind === 'videoinput');
            setHasMultipleCameras(videoDevices.length > 1);

        } catch (err) {
            console.error('Camera error:', err);
            if (err.name === 'NotAllowedError' || err.name === 'PermissionDeniedError') {
                setError('Camera access denied. Please enable camera permissions in your browser settings.');
            } else if (err.name === 'NotFoundError' || err.name === 'DevicesNotFoundError') {
                setError('No camera detected. Please ensure your camera is connected.');
            } else if (err.name === 'NotReadableError') {
                setError('Camera is in use by another application. Please close it and try again.');
            } else {
                setError(`Camera error: ${err.message}`);
            }
        } finally {
            setIsLoading(false);
        }
    }, [facingMode, stopStream]);

    useEffect(() => {
        if (isOpen) {
            startStream();
        } else {
            stopStream();
        }
        return () => stopStream();
    }, [isOpen]);

    useEffect(() => {
        if (isOpen) {
            startStream();
        }
    }, [facingMode]);

    const handleSwitchCamera = () => {
        setFacingMode(prev => prev === 'environment' ? 'user' : 'environment');
    };

    const handleCapture = () => {
        if (!videoRef.current || !canvasRef.current) return;

        const video = videoRef.current;
        const canvas = canvasRef.current;
        const context = canvas.getContext('2d');

        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        
        // Final Mirror compensation for captured image
        if (facingMode === 'user') {
            context.translate(canvas.width, 0);
            context.scale(-1, 1);
        }
        
        context.drawImage(video, 0, 0, canvas.width, canvas.height);
        
        // Reset transform to draw watermark correctly
        if (facingMode === 'user') {
            context.setTransform(1, 0, 0, 1, 0, 0);
        }

        // Draw Professional GPS Watermark/Stamp
        if (metadata) {
            const padding = canvas.width * 0.02;
            const logoSize = canvas.width * 0.04;
            const fontSizeMain = Math.max(14, canvas.width * 0.018);
            const fontSizeSmall = Math.max(10, canvas.width * 0.012);
            const timestamp = new Date().toLocaleString();

            // 1. Semi-transparent backdrop for the entire watermark zone
            const boxWidth = canvas.width * 0.45;
            const boxHeight = canvas.height * 0.18;
            // 1. No card backdrop - drawing directly on canvas
            // We still use boxX, boxY for layout alignment
            const boxX = padding;
            const boxY = canvas.height - boxHeight - padding;

            // Added a slight shadow to the text for legibility without a box
            context.shadowColor = 'rgba(0, 0, 0, 0.8)';
            context.shadowBlur = 4;
            context.shadowOffsetX = 2;
            context.shadowOffsetY = 2;

            // 2. Draw "PULSO GPS VERIFIED" header with green dot
            context.fillStyle = '#22c55e'; // Green
            context.beginPath();
            context.arc(boxX + 20, boxY + 25, 4, 0, Math.PI * 2);
            context.fill();

            context.font = `black ${fontSizeSmall}px system-ui, -apple-system, sans-serif`;
            context.fillStyle = 'white';
            context.fillText(`PULSO GPS VERIFIED • ${timestamp}`, boxX + 35, boxY + 28);

            // 3. Draw Coordinates
            context.font = `bold ${fontSizeMain}px monospace`;
            context.fillStyle = '#f97316'; // Orange
            context.fillText('LAT', boxX + 20, boxY + 60);
            context.fillStyle = 'white';
            context.fillText(metadata.lat?.toFixed(6) || '0.000000', boxX + 80, boxY + 60);

            context.fillStyle = '#f97316';
            context.fillText('LNG', boxX + 20, boxY + 90);
            context.fillStyle = 'white';
            context.fillText(metadata.lng?.toFixed(6) || '0.000000', boxX + 80, boxY + 90);

            // 4. Draw Address (Truncated for clean look)
            if (metadata.address) {
                context.font = `bold ${fontSizeSmall}px system-ui, -apple-system, sans-serif`;
                context.fillStyle = 'rgba(255, 255, 255, 0.8)';
                const addressLines = [
                    metadata.address.slice(0, 45),
                    metadata.address.length > 45 ? metadata.address.slice(45, 90) : ''
                ];
                addressLines.forEach((line, i) => {
                    context.fillText(line, boxX + 20, boxY + 120 + (i * 18));
                });
            }
            
            // Reset shadows for any potential subsequent drawing
            context.shadowBlur = 0;
            context.shadowOffsetX = 0;
            context.shadowOffsetY = 0;
        }

        canvas.toBlob((blob) => {
            if (blob) {
                // Name file with GPS coordinates for on-site proof
                const lat = metadata?.lat?.toFixed(6) || '0.000000';
                const lng = metadata?.lng?.toFixed(6) || '0.000000';
                const ts = Math.floor(Date.now() / 1000);
                const gpsFilename = `PULSO_${lat}_${lng}_${ts}.jpg`;
                const file = new File([blob], gpsFilename, { type: 'image/jpeg' });
                onCapture(file);
                onClose();
            }
        }, 'image/jpeg', 0.95);
    };

    return (
        <AnimatePresence>
            {isOpen && (
                <motion.div
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    exit={{ opacity: 0 }}
                    className="fixed inset-0 z-[200] flex items-center justify-center bg-black/70 backdrop-blur-xl p-4 sm:p-6"
                >
                    <motion.div
                        initial={{ scale: 0.9, opacity: 0, y: 20 }}
                        animate={{ scale: 1, opacity: 1, y: 0 }}
                        exit={{ scale: 0.9, opacity: 0, y: 20 }}
                        className="relative w-full max-w-2xl 
                            bg-white dark:bg-slate-900 
                            border border-gray-200 dark:border-slate-800 
                            rounded-3xl overflow-hidden shadow-2xl flex flex-col h-full 
                            max-h-[95vh] sm:max-h-[85vh]"
                    >
                        {/* Header */}
                        <div className="flex items-center justify-between p-4 sm:p-5 
                            border-b border-gray-200 dark:border-slate-800
                            bg-white dark:bg-slate-900">
                            <div>
                                {title ? (
                                    <h3 className="font-bold text-base sm:text-lg text-gray-900 dark:text-white uppercase truncate max-w-[200px] sm:max-w-none">
                                        {title}
                                    </h3>
                                ) : (
                                    <h3 className="font-bold text-base sm:text-lg text-gray-900 dark:text-white">
                                        ID Camera Capture
                                    </h3>
                                )}
                                {subtitle ? (
                                    <p className="text-[10px] sm:text-xs text-gray-500 dark:text-slate-400">
                                        {subtitle}
                                    </p>
                                ) : (
                                    <p className="text-[10px] sm:text-xs text-gray-500 dark:text-slate-400">
                                        {side === 'ISSUE' ? (
                                            "Capture a clear photo of the infrastructure issue for AI verification"
                                        ) : (
                                            <>
                                                Capture the{' '}
                                                <span className="text-orange-500 font-bold uppercase">{side}</span>
                                                {' '}of your ID
                                            </>
                                        )}
                                    </p>
                                )}
                            </div>
                            <button
                                onClick={onClose}
                                className="p-2 sm:p-2.5 rounded-full 
                                    bg-gray-100 dark:bg-slate-800 
                                    text-gray-500 dark:text-slate-400 
                                    hover:bg-gray-200 dark:hover:bg-slate-700 
                                    hover:text-gray-900 dark:hover:text-white 
                                    transition-all"
                            >
                                <X size={18} className="sm:hidden" />
                                <X size={20} className="hidden sm:block" />
                            </button>
                        </div>

                        {/* Early Advice Banner */}
                        {side !== 'ISSUE' && (
                            <div className="bg-orange-500/10 border-b border-orange-500/20 px-4 py-2.5 flex items-center gap-3">
                                <AlertCircle size={16} className="text-orange-500 shrink-0" />
                                <p className="text-[11px] font-bold text-orange-200 leading-tight">
                                    <span className="text-orange-500 uppercase">Early Advice:</span> Verify all scanned details manually.
                                    The OCR engine is in experimental development.
                                </p>
                            </div>
                        )}

                        {/* Camera Preview */}
                        <div className="relative flex-1 bg-black flex items-center justify-center overflow-hidden">
                            {error ? (
                                <div className="text-center p-8 
                                    bg-white dark:bg-slate-900 
                                    w-full h-full flex flex-col items-center justify-center">
                                    <AlertCircle size={48} className="text-red-500 mx-auto mb-4" />
                                    <p className="font-medium mb-4
                                        text-gray-800 dark:text-white">
                                        {error}
                                    </p>
                                    <button
                                        onClick={startStream}
                                        className="px-6 py-2.5 bg-orange-500 text-white rounded-xl font-bold text-sm hover:bg-orange-600 transition-all"
                                    >
                                        Retry Camera Access
                                    </button>
                                </div>
                            ) : (
                                <>
                                    <video
                                        ref={videoRef}
                                        autoPlay
                                        playsInline
                                        muted
                                        className={`w-full h-full object-cover ${facingMode === 'user' ? 'scale-x-[-1]' : ''}`}
                                    />

                                    {/* Camera UI Overlays */}
                                    <div className="absolute inset-0 pointer-events-none flex flex-col items-center justify-between p-6">
                                        {/* Top spacer or potential top-aligned UI */}
                                        <div />

                                        {/* Middle-Bottom Guide text (Floating Pill) */}
                                        <div className="mb-32">
                                            <span className="text-white text-[11px] sm:text-xs font-bold tracking-wide drop-shadow-lg bg-black/40 px-4 py-2 rounded-full border border-white/10 backdrop-blur-md">
                                                {guideText || "Center the issue in your view"}
                                            </span>
                                        </div>
                                    </div>

                                    {/* Geospatial Metadata Overlay */}
                                    {metadata && (
                                        <div className="absolute bottom-4 left-4 right-4 pointer-events-none flex flex-col items-start gap-1">
                                            <div className="flex flex-col gap-1.5 drop-shadow-[0_2px_4px_rgba(0,0,0,0.8)]">
                                                <div className="flex items-center gap-2 mb-1">
                                                    <div className="w-2.5 h-2.5 rounded-full bg-green-500 animate-pulse border border-white/20 shadow-[0_0_8px_rgba(34,197,94,0.6)]" />
                                                    <span className="text-[11px] font-black text-white uppercase tracking-[0.25em]">PULSO GPS LENS</span>
                                                </div>
                                                <div className="flex flex-col gap-1 pl-4.5">
                                                    <div className="flex items-center gap-3">
                                                        <span className="text-[10px] font-black text-orange-500 w-8 uppercase">LAT</span>
                                                        <span className="text-[13px] font-mono font-bold text-white tracking-tight">{metadata.lat?.toFixed(6)}</span>
                                                    </div>
                                                    <div className="flex items-center gap-3">
                                                        <span className="text-[10px] font-black text-orange-500 w-8 uppercase">LNG</span>
                                                        <span className="text-[13px] font-mono font-bold text-white tracking-tight">{metadata.lng?.toFixed(6)}</span>
                                                    </div>
                                                    {metadata.address && (
                                                        <div className="flex items-start gap-2 mt-2 border-t border-white/20 pt-2 max-w-[280px] sm:max-w-[350px]">
                                                            <MapPin size={11} className="text-orange-500 mt-0.5 shrink-0" />
                                                            <span className="text-[11px] font-bold text-white/90 leading-tight tracking-wide">{metadata.address}</span>
                                                        </div>
                                                    )}
                                                </div>
                                            </div>
                                        </div>
                                    )}

                                    {isLoading && (
                                        <div className="absolute inset-0 
                                            bg-white dark:bg-slate-900 
                                            flex flex-col items-center justify-center">
                                            <div className="w-12 h-12 border-4 
                                                border-gray-200 dark:border-slate-700 
                                                border-t-orange-500 rounded-full animate-spin mb-4" />
                                            <p className="text-sm font-medium
                                                text-gray-500 dark:text-slate-400">
                                                Initializing camera...
                                            </p>
                                        </div>
                                    )}
                                </>
                            )}
                            <canvas ref={canvasRef} className="hidden" />
                        </div>

                        {/* Controls */}
                        <div className="p-4 sm:p-6 
                            bg-white dark:bg-slate-900 
                            border-t border-gray-200 dark:border-slate-800 
                            flex items-center justify-between gap-4 sm:gap-6">

                            {/* Switch Camera */}
                            <div className="w-10 sm:w-12">
                                {hasMultipleCameras && !error && (
                                    <button
                                        onClick={handleSwitchCamera}
                                        className="p-2 sm:p-3.5 rounded-full 
                                            bg-gray-100 dark:bg-slate-800 
                                            text-gray-700 dark:text-white 
                                            hover:bg-gray-200 dark:hover:bg-slate-700 
                                            transition-all group"
                                        title="Switch Camera"
                                    >
                                        <RefreshCw size={18} className="sm:hidden group-active:rotate-180 transition-transform duration-500" />
                                        <RefreshCw size={22} className="hidden sm:block group-active:rotate-180 transition-transform duration-500" />
                                    </button>
                                )}
                            </div>

                            {/* Capture Button */}
                            <button
                                onClick={handleCapture}
                                disabled={!streamRef.current || isLoading || !!error}
                                className="w-14 h-14 sm:w-18 sm:h-18 rounded-full 
                                    bg-white dark:bg-slate-700
                                    flex items-center justify-center 
                                    border-[4px] sm:border-[6px] border-gray-300 dark:border-slate-600
                                    hover:scale-105 active:scale-95 transition-all shadow-2xl 
                                    disabled:opacity-50 disabled:cursor-not-allowed group"
                            >
                                <div className="w-10 h-10 sm:w-12 sm:h-12 rounded-full bg-orange-500 group-hover:bg-orange-600 transition-colors" />
                            </button>

                            {/* Live Indicator */}
                            <div className="w-10 sm:w-12 flex flex-col items-center 
                                text-gray-400 dark:text-slate-500">
                                <div className="relative">
                                    <CameraOff size={18} className="sm:hidden mb-0.5" />
                                    <CameraOff size={20} className="hidden sm:block mb-0.5" />
                                    {/* Live dot */}
                                    {streamRef.current && !isLoading && (
                                        <span className="absolute -top-1 -right-1 w-1.5 h-1.5 sm:w-2 sm:h-2 bg-green-500 rounded-full animate-pulse" />
                                    )}
                                </div>
                                <span className="text-[8px] sm:text-[9px] font-bold uppercase tracking-tighter">
                                    {streamRef.current && !isLoading ? 'Live' : 'Off'}
                                </span>
                            </div>
                        </div>
                    </motion.div>
                </motion.div>
            )}
        </AnimatePresence>
    );
};

export default IDCameraModal;

import React from 'react';
import { useTranslation } from 'react-i18next';
import { useLocation } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { Languages } from 'lucide-react';

export default function LanguageSwitcher() {
    const { i18n } = useTranslation();
    const location = useLocation();
    const [isOpen, setIsOpen] = React.useState(false);

    // Hide on all government/internal dashboard pages
    if (
        location.pathname.startsWith('/gov') ||
        location.pathname.startsWith('/management') ||
        location.pathname.startsWith('/dispatcher')
    ) {
        return null;
    }

    const changeLanguage = (lng) => {
        i18n.changeLanguage(lng);
        setIsOpen(false);
    };

    const currentLang = i18n.language || 'en';

    return (
        <div className="fixed bottom-6 right-6 z-[9999]">
            <AnimatePresence>
                {isOpen && (
                    <motion.div
                        initial={{ opacity: 0, y: 10, scale: 0.95 }}
                        animate={{ opacity: 1, y: 0, scale: 1 }}
                        exit={{ opacity: 0, y: 10, scale: 0.95 }}
                        transition={{ duration: 0.2 }}
                        className="absolute bottom-16 right-0 w-36 rounded-xl bg-white dark:bg-gray-800 shadow-2xl border border-gray-100 dark:border-gray-700 overflow-hidden"
                    >
                        <button
                            onClick={() => changeLanguage('en')}
                            className={`w-full flex items-center gap-3 px-4 py-3 text-sm transition-colors ${currentLang === 'en'
                                ? 'bg-orange-50 dark:bg-orange-900/30 text-orange-600 dark:text-orange-400 font-bold'
                                : 'text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700/50 font-medium'
                                }`}
                        >
                            <img src="https://flagcdn.com/w20/us.png" srcSet="https://flagcdn.com/w40/us.png 2x" width="20" alt="US" className="rounded-sm shadow-sm" /> English
                        </button>
                        <div className="h-px w-full bg-gray-100 dark:bg-gray-700" />
                        <button
                            onClick={() => changeLanguage('tl')}
                            className={`w-full flex items-center gap-3 px-4 py-3 text-sm transition-colors ${currentLang === 'tl'
                                ? 'bg-orange-50 dark:bg-orange-900/30 text-orange-600 dark:text-orange-400 font-bold'
                                : 'text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700/50 font-medium'
                                }`}
                        >
                            <img src="https://flagcdn.com/w20/ph.png" srcSet="https://flagcdn.com/w40/ph.png 2x" width="20" alt="PH" className="rounded-sm shadow-sm" /> Tagalog
                        </button>
                    </motion.div>
                )}
            </AnimatePresence>

            <motion.button
                onClick={() => setIsOpen(!isOpen)}
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
                className="flex items-center justify-center w-14 h-14 rounded-full bg-orange-500 text-white shadow-xl shadow-orange-500/30 hover:bg-orange-600 hover:shadow-orange-600/40 transition-all focus:outline-none focus:ring-2 focus:ring-orange-500 focus:ring-offset-2 dark:focus:ring-offset-gray-900"
                aria-label="Toggle language"
            >
                <Languages size={24} />
            </motion.button>
        </div>
    );
}

