// ─── Main Dashboard ───────────────────────────────────────────────────────────

const TABS = [
    { id: 'overview',  label: 'Overview',       icon: BarChart2 },
    { id: 'health',    label: 'Asset Health',   icon: Activity },
    { id: 'schedule',  label: 'Schedule',       icon: Calendar },
    { id: 'risk-map',  label: 'Risk Map',       icon: MapPin },
];

export default function PredictiveMaintenance() {
    const [activeTab, setActiveTab] = useState('overview');
    const [summary, setSummary] = useState(null);
    const [health, setHealth] = useState([]);
    const [schedule, setSchedule] = useState(null);
    const [riskMap, setRiskMap] = useState([]);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState(null);
    const [loadingAI, setLoadingAI] = useState(null);
    const [convertingWO, setConvertingWO] = useState(false);
    const [aiPlan, setAiPlan] = useState(null);
    const [filterPriority, setFilterPriority] = useState('ALL');
    const [lastRefresh, setLastRefresh] = useState(null);
    const [expandedIds, setExpandedIds] = useState(new Set());

    const loadAll = useCallback(async () => {
        setLoading(true);
        setError(null);
        try {
            const [sum, hlth, sched, risk] = await Promise.all([
                apiFetch('/api/gov/predictive/summary'),
                apiFetch('/api/gov/predictive/health'),
                apiFetch('/api/gov/predictive/schedule'),
                apiFetch('/api/gov/predictive/risk-map'),
            ]);
            setSummary(sum);
            setHealth(hlth.health_scores || []);
            setSchedule(sched);
            setRiskMap(risk.risk_map || []);
            setLastRefresh(new Date());
        } catch (e) {
            setError(e.message);
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => { loadAll(); }, [loadAll]);

    const handleAIPlan = async (asset) => {
        if (!asset) return;
        if (asset.dismiss) {
            setHealth(prev => prev.map(a => 
                (a.barangay === asset.barangay && a.category === asset.category) 
                ? { ...a, ai_plan: null } 
                : a
            ));
            return;
        }
        const key = `${asset.barangay}_${asset.category}`;
        setLoadingAI(key);
        try {
            const plan = await apiFetch('/api/gov/predictive/ai-plan', {
                method: 'POST',
                body: JSON.stringify({ 
                    barangay: asset.barangay, 
                    category: asset.category, 
                    asset_id: asset.asset_id 
                }),
            });
            // Update the specific asset in health state with the plan
            setHealth(prev => prev.map(a => 
                (a.barangay === asset.barangay && a.category === asset.category) 
                ? { ...a, ai_plan: plan } 
                : a
            ));
        } catch (e) {
            alert(`AI Plan Error: ${e.message}`);
        } finally {
            setLoadingAI(null);
        }
    };

    const handleConvertPlanToWO = async (plan) => {
        if (!confirm(`Are you sure you want to convert this AI plan for ${plan.category} in Brgy. ${plan.barangay} into a formal Work Order?`)) return;
        
        setConvertingWO(true);
        try {
            const wo = await apiFetch('/api/gov/predictive/convert-to-work-order', {
                method: 'POST',
                body: JSON.stringify({
                    barangay: plan.barangay,
                    category: plan.category,
                    plan_summary: plan.maintenance_plan,
                    priority: plan.priority,
                    estimated_cost: plan.estimated_cost || 0,
                    asset_id: plan.asset_id,
                }),
            });
            alert(`Success! Work Order #${wo.wo_number} has been created and dispatched.`);
            setAiPlan(null);
            loadAll();
        } catch (e) {
            alert(`Conversion Error: ${e.message}`);
        } finally {
            setConvertingWO(false);
        }
    };

    const handleExport = async () => {
        const token = getToken();
        const res = await fetch(`${API}/api/gov/predictive/export`, {
            headers: { Authorization: `Bearer ${token}` },
        });
        const blob = await res.blob();
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `PULSO_PredictiveMaint_${new Date().toISOString().slice(0,10)}.csv`;
        a.click();
    };

    const filteredHealth = filterPriority === 'ALL'
        ? health
        : health.filter(a => a.priority === filterPriority);

    return (
        <div className="flex-1 flex flex-col min-h-0 bg-slate-50 dark:bg-slate-950">
            {/* Header */}
            <div className="bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800 px-6 py-4 shrink-0 shadow-sm">
                <div className="flex items-center justify-between">
                    <div>
                        <div className="flex items-center gap-3">
                            <div className="w-9 h-9 rounded-xl bg-gradient-to-br from-violet-500 to-purple-700 flex items-center justify-center shadow-md">
                                <Cpu size={18} className="text-white" />
                            </div>
                            <div>
                                <h1 className="text-lg font-black text-slate-900 dark:text-white">Predictive Maintenance Engine</h1>
                                <p className="text-xs text-slate-500">AI-driven infrastructure failure forecasting · Caloocan City Engineering Office</p>
                            </div>
                        </div>
                    </div>
                    <div className="flex items-center gap-2">
                        {lastRefresh && (
                            <span className="text-[10px] text-slate-400">
                                Updated {lastRefresh.toLocaleTimeString('en-PH')}
                            </span>
                        )}
                        <button onClick={handleExport} className="flex items-center gap-1.5 text-xs font-bold px-3 py-2 rounded-xl border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors">
                            <Download size={13} /> Export CSV
                        </button>
                        <button
                            onClick={loadAll}
                            disabled={loading}
                            className="flex items-center gap-1.5 text-xs font-bold px-3 py-2 rounded-xl bg-indigo-600 hover:bg-indigo-700 text-white transition-colors"
                        >
                            <RefreshCw size={13} className={loading ? 'animate-spin' : ''} />
                            Refresh
                        </button>
                    </div>
                </div>

                {/* Tabs */}
                <div className="flex gap-1 mt-4">
                    {TABS.map(tab => (
                        <button
                            key={tab.id}
                            onClick={() => setActiveTab(tab.id)}
                            className={`flex items-center gap-1.5 px-3 py-2 rounded-lg text-xs font-bold transition-all ${
                                activeTab === tab.id
                                    ? 'bg-indigo-600 text-white shadow-sm'
                                    : 'text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800'
                            }`}
                        >
                            <tab.icon size={13} />
                            {tab.label}
                        </button>
                    ))}
                </div>
            </div>

            {/* Body */}
            <div className="flex-1 overflow-y-auto p-6">
                {error && (
                    <div className="mb-4 bg-red-50 dark:bg-red-950/30 border border-red-200 dark:border-red-800 rounded-xl p-4 flex items-center gap-3 text-sm text-red-600 dark:text-red-400">
                        <AlertTriangle size={16} />
                        <span><strong>Error:</strong> {error}</span>
                        <button onClick={loadAll} className="ml-auto text-red-500 hover:text-red-700 font-bold text-xs">Retry</button>
                    </div>
                )}

                {loading && !summary ? (
                    <div className="flex items-center justify-center py-20">
                        <div className="text-center">
                            <div className="w-12 h-12 rounded-2xl bg-gradient-to-br from-violet-500 to-purple-700 flex items-center justify-center mx-auto mb-3 animate-pulse">
                                <Cpu size={22} className="text-white" />
                            </div>
                            <div className="text-sm font-bold text-slate-500">Running predictive analysis…</div>
                            <div className="text-xs text-slate-400 mt-1">Scanning {health?.length || '…'} infrastructure assets</div>
                        </div>
                    </div>
                ) : (
                    <>
                        {/* ── OVERVIEW TAB ───────────────────────── */}
                        {activeTab === 'overview' && summary && (
                            <div className="space-y-6">
                                {/* Rainy season banner */}
                                {summary.rainy_season_active && (
                                    <div className="bg-blue-600 rounded-2xl p-4 flex items-center gap-4">
                                        <CloudRain size={32} className="text-white shrink-0" />
                                        <div>
                                            <div className="font-black text-white">Rainy Season Alert</div>
                                            <div className="text-blue-100 text-xs">
                                                June–November is high-risk period for drainage, roads, and flooding.
                                                Priority maintenance should be completed before peak rainfall.
                                            </div>
                                        </div>
                                    </div>
                                )}

                                {/* KPI grid */}
                                <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-4">
                                    <KPICard icon={Shield} label="Assets Monitored" value={summary.total_assets_monitored || 0} color="indigo" />
                                    <KPICard icon={Activity} label="Avg Health Score" value={`${summary.avg_health_score || 0}/100`} color="blue" />
                                    <KPICard icon={AlertOctagon} label="Critical Assets" value={summary.critical_count || 0} color="red" pulse={summary.critical_count > 0} />
                                    <KPICard icon={AlertTriangle} label="High Priority" value={summary.high_count || 0} color="orange" />
                                    <KPICard icon={Clock} label="Urgent This Week" value={summary.urgent_this_week || 0} color="yellow" />
                                    <KPICard icon={Zap} label="Immediate Action Needed" value={summary.assets_needing_immediate_action || 0} color="red" pulse={summary.assets_needing_immediate_action > 0} />
                                    <KPICard icon={ClipboardList} label="90-Day Budget" value={summary.scheduled_90d_cost_formatted || '₱0'} color="purple" />
                                    <KPICard icon={CheckCircle} label="Good Condition" value={summary.good_count || 0} color="green" />
                                    {summary.total_active_reports > 0 && (
                                        <KPICard icon={BarChart2} label="Active Reports Analyzed" value={summary.total_active_reports} color="indigo"
                                            sub="Source: Analytics Command Center" />
                                    )}
                                </div>

                                {/* Top at-risk */}
                                {summary.top_at_risk?.length > 0 && (
                                    <div className="bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 p-5 shadow-md shadow-orange-100/60 dark:shadow-orange-900/10">
                                        <div className="flex items-center gap-2 mb-4">
                                            <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-red-500 to-rose-700 flex items-center justify-center shadow-md">
                                                <AlertOctagon size={14} className="text-white" />
                                            </div>
                                            <h2 className="font-black text-slate-900 dark:text-white">Top 5 At-Risk Assets</h2>
                                        </div>
                                        <div className="space-y-3">
                                            {summary.top_at_risk.map((asset, i) => {
                                                const cfg = PRIORITY_CONFIG[asset.priority] || PRIORITY_CONFIG.WATCH;
                                                return (
                                                    <div key={i} className={`${cfg.bg} ${cfg.border} border rounded-xl p-3 flex items-center gap-3`}>
                                                        <div className={`shrink-0 min-w-[3rem] text-center`}>
                                                            <div className={`text-xl font-black leading-none ${cfg.text}`}>{Math.round(asset.health_score)}</div>
                                                            <div className="text-[9px] text-slate-400 font-bold">/ 100</div>
                                                        </div>
                                                        <div className={`w-px self-stretch ${cfg.border} border-l shrink-0`} />
                                                        <div className="flex-1 min-w-0">
                                                            <div className="font-bold text-slate-800 dark:text-slate-200 text-sm truncate">{asset.category.toUpperCase()}</div>
                                                            <div className="text-xs text-slate-500 truncate">Brgy. {asset.barangay} · {Math.round(asset.failure_probability_30d * 100)}% fail risk</div>
                                                            <HealthBar score={asset.health_score} size="sm" />
                                                        </div>
                                                        <span className={`text-[10px] font-black px-2 py-0.5 rounded-full text-white shrink-0 ${cfg.badge}`}>
                                                            {cfg.label}
                                                        </span>
                                                    </div>
                                                );
                                            })}
                                        </div>
                                    </div>
                                )}
                            </div>
                        )}

                        {/* ── ASSET HEALTH TAB ───────────────────── */}
                        {activeTab === 'health' && (
                            <div className="space-y-4">
                                {/* Header */}
                                <div className="flex items-center justify-between">
                                    <h3 className="font-black text-slate-800 dark:text-white uppercase tracking-wider text-sm">Real-time Asset Health</h3>
                                    <div className="flex items-center gap-2 flex-wrap justify-end">
                                        {['ALL', 'CRITICAL', 'HIGH', 'MODERATE', 'WATCH', 'GOOD'].map(p => (
                                            <button
                                                key={p}
                                                onClick={() => setFilterPriority(p)}
                                                className={`text-[10px] font-black uppercase px-2.5 py-1.5 rounded-lg border transition-all ${
                                                    filterPriority === p
                                                        ? 'bg-indigo-600 border-indigo-600 text-white shadow-md'
                                                        : 'border-slate-200 dark:border-slate-700 text-slate-500 hover:bg-slate-50 dark:hover:bg-slate-800'
                                                }`}
                                            >
                                                {p === 'ALL' ? `All (${health.length})` : `${p}`}
                                            </button>
                                        ))}
                                    </div>
                                </div>
                                {filteredHealth.length === 0 ? (
                                    <div className="text-center py-12 text-slate-400">
                                        <Shield size={32} className="mx-auto mb-2 opacity-30" />
                                        <div className="font-bold">No assets match this filter.</div>
                                        <div className="text-xs mt-1">Try changing the priority filter or ensure reports exist in the system.</div>
                                    </div>
                                ) : (
                                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 items-start">
                                        {filteredHealth.map((asset, i) => {
                                            const cardId = `asset_${i}_${asset.barangay}_${asset.category}`;
                                            return (
                                                <HealthCard 
                                                    key={cardId} 
                                                    asset={asset} 
                                                    onAIPlan={handleAIPlan} 
                                                    onConvertToWO={handleConvertPlanToWO}
                                                    loadingAI={loadingAI}
                                                    isExpanded={expandedIds.has(cardId)}
                                                    onToggle={() => {
                                                        const next = new Set(expandedIds);
                                                        if (next.has(cardId)) next.delete(cardId);
                                                        else next.add(cardId);
                                                        setExpandedIds(next);
                                                    }}
                                                />
                                            );
                                        })}
                                    </div>
                                )}
                            </div>
                        )}

                        {/* ── SCHEDULE TAB ───────────────────────── */}
                        {activeTab === 'schedule' && (
                            <ScheduleView schedule={schedule} />
                        )}

                        {/* ── RISK MAP TAB ───────────────────────── */}
                        {activeTab === 'risk-map' && (
                            <div className="space-y-4">
                                <div className="flex items-center gap-3 p-3 bg-blue-50 dark:bg-blue-950/30 border border-blue-100 dark:border-blue-900 rounded-xl text-xs text-blue-700 dark:text-blue-400">
                                    <Info size={14} className="shrink-0" />
                                    Barangay risk is aggregated from all monitored infrastructure categories. Lower health score = higher risk.
                                </div>
                                <RiskMapView riskMap={riskMap} />
                            </div>
                        )}
                    </>
                )}
            </div>

        </div>
    );
}

import React, { useState, useEffect } from 'react';
import { motion, useScroll, useTransform, useSpring } from 'framer-motion';

/**
 * PremiumHeroBackground
 * ─────────────────────────────────────────────────────────────────────────────
 * A high-performance, purely CSS & Framer Motion based background system
 * that mimics the "Spline" aesthetic (lighting, depth, and glassmorphism)
 * without the overhead of a 3D engine.
 * ─────────────────────────────────────────────────────────────────────────────
 */
const PremiumHeroBackground = ({ children }) => {
    const [mousePos, setMousePos] = useState({ x: 0, y: 0 });
    const { scrollY } = useScroll();

    // Smoothen the scroll value for parallax
    const smoothY = useSpring(scrollY, { stiffness: 100, damping: 30 });
    const parallaxY = useTransform(smoothY, [0, 1000], [0, -200]);

    useEffect(() => {
        const handleMouseMove = (e) => {
            setMousePos({
                x: (e.clientX / window.innerWidth - 0.5) * 40,
                y: (e.clientY / window.innerHeight - 0.5) * 40
            });
        };
        window.addEventListener('mousemove', handleMouseMove);
        return () => window.removeEventListener('mousemove', handleMouseMove);
    }, []);

    return (
        <div className="fixed inset-0 z-0 overflow-hidden pointer-events-none bg-white dark:bg-[#020617] transition-colors duration-1000">
            {/* 1. Deep Space Layer — Atmospheric Glows */}
            <div className="absolute inset-0">
                {/* Primary Orange Glow — Reacts to mouse */}
                <motion.div
                    animate={{
                        x: mousePos.x * 1.5,
                        y: mousePos.y * 1.5,
                        scale: [1, 1.1, 1],
                    }}
                    transition={{ scale: { duration: 10, repeat: Infinity, ease: "easeInOut" } }}
                    className="absolute -top-[10%] -right-[5%] w-[60vw] h-[60vw] rounded-full 
                    bg-[radial-gradient(circle,rgba(249,115,22,0.18)_0%,transparent_70%)] 
                    filter blur-[120px] opacity-80 pointer-events-none"
                />

                {/* Cyber Blue Secondary Glow */}
                <motion.div
                    animate={{
                        x: -mousePos.x,
                        y: -mousePos.y,
                        scale: [1, 1.2, 1],
                    }}
                    transition={{ scale: { duration: 15, repeat: Infinity, ease: "easeInOut" } }}
                    className="absolute -bottom-[10%] -left-[5%] w-[50vw] h-[50vw] rounded-full 
                    bg-[radial-gradient(circle,rgba(56,189,248,0.15)_0%,transparent_70%)] 
                    filter blur-[120px] opacity-80 pointer-events-none"
                />
            </div>

            {/* 2. Engineering Grid Layer — Mimics Command Center Depth */}
            <motion.div 
                style={{ y: parallaxY }}
                className="absolute inset-0 opacity-[0.4] dark:opacity-[0.1]"
            >
                <div 
                    className="absolute inset-0"
                    style={{
                        backgroundImage: `
                            linear-gradient(to right, currentColor 1px, transparent 1px),
                            linear-gradient(to bottom, currentColor 1px, transparent 1px)
                        `,
                        backgroundSize: '40px 40px',
                        maskImage: 'radial-gradient(circle at 50% 50%, black, transparent 80%)'
                    }}
                />
            </motion.div>

            {/* 3. CENTER SCENE LAYER — This is where the 3D Map goes */}
            <div className="absolute inset-0 z-10 pointer-events-auto">
                {children}
            </div>

            {/* 4. Floating Glass Elements — Repositioned to frame the center map */}
            <div className="absolute inset-0 perspective-[2000px] z-20">
                {/* Floating Glass Orb 1 — Moved to Top-Left */}
                <motion.div
                    animate={{
                        y: [0, -20, 0],
                        rotateX: mousePos.y * 0.4,
                        rotateY: mousePos.x * 0.4,
                        x: mousePos.x * 0.5
                    }}
                    transition={{ y: { duration: 7, repeat: Infinity, ease: "easeInOut" } }}
                    className="absolute top-[10%] left-[5%] w-40 h-40 rounded-full flex items-center justify-center
                    bg-white/10 dark:bg-white/5 backdrop-blur-[10px]
                    border border-white/20 dark:border-white/10
                    shadow-xl
                    before:absolute before:inset-0 before:rounded-full before:bg-gradient-to-tr before:from-blue-500/10 before:to-transparent"
                >
                    <img src="/engineering-logo.jpg" alt="City Engineering" className="w-24 h-24 object-contain rounded-full relative z-10 shadow-lg" />
                </motion.div>

                {/* Floating Glass Orb 2 — Moved to Bottom-Right */}
                <motion.div
                    animate={{
                        y: [0, 20, 0],
                        rotateX: mousePos.y * -0.3,
                        rotateY: mousePos.x * -0.3,
                        x: mousePos.x * -0.4
                    }}
                    transition={{ y: { duration: 9, repeat: Infinity, ease: "easeInOut" }, delay: 1 }}
                    className="absolute bottom-[15%] right-[5%] w-32 h-32 rounded-3xl flex items-center justify-center
                    bg-white/5 dark:bg-white/[0.04] backdrop-blur-[8px]
                    border border-white/20 dark:border-white/5
                    shadow-xl rotate-12
                    before:absolute before:inset-0 before:rounded-3xl before:bg-gradient-to-bl before:from-orange-500/10 before:to-transparent"
                >
                    <img src="/pulso-logo.png" alt="PULSO Logo" className="w-20 h-20 object-contain relative z-10 drop-shadow-lg" />
                </motion.div>
            </div>

            {/* 5. Refined Noise Grain */}
            <div className="absolute inset-0 bg-transparent opacity-[0.03] dark:opacity-[0.05] pointer-events-none mix-blend-overlay z-30">
                <svg viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg">
                    <filter id="noise">
                        <feTurbulence type="fractalNoise" baseFrequency="0.65" numOctaves="3" stitchTiles="stitch" />
                    </filter>
                    <rect width="100%" height="100%" filter="url(#noise)" />
                </svg>
            </div>

            {/* 6. Edge vignette */}
            <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_50%,transparent_0%,rgba(2,6,23,0.1)_100%)] pointer-events-none z-40" />
        </div>
    );
};

export default PremiumHeroBackground;

/**
 * ProtectedRoute.jsx
 * ──────────────────────────────────────────────────────────────────────
 * Gate component for role-based access control on all frontend routes.
 *
 * Usage:
 *   <ProtectedRoute allowedRoles={['city_engineer', 'asst_city_engineer']}>
 *     <SomeAdminPage />
 *   </ProtectedRoute>
 *
 * Behavior:
 *   - Not logged in         → redirect to /login
 *   - Logged in, wrong role → show UnauthorizedPage
 *   - Logged in, right role → render children
 *
 * Pass allowedRoles={null} or omit it to allow ANY authenticated user.
 */

import React from 'react';
import { Navigate, useLocation } from 'react-router-dom';
import { ShieldX, LogOut, ChevronLeft } from 'lucide-react';
import { checkPermission } from '../utils/rbac_utils';

// ─────────────────────────────────────────────────────────────────────────────
// Role groups (mirroring backend)
// ─────────────────────────────────────────────────────────────────────────────
export const GOV_ROLES = [
    'city_engineer', 'asst_city_engineer', 'admin_officer', 'admin_clerk',
    'records_officer', 'division_chief', 'design_engineer', 'estimator',
    'cad_operator', 'project_engineer', 'construction_foreman', 'field_worker',
    'building_inspector', 'electrical_inspector', 'mechanical_inspector',
    'dispatcher', 'manager', 'system_admin',
];

export const EXECUTIVE_ROLES = ['city_engineer', 'asst_city_engineer', 'manager', 'system_admin'];
export const SENIOR_ROLES    = ['city_engineer', 'asst_city_engineer', 'admin_officer', 'division_chief', 'manager', 'system_admin'];
export const INSPECTOR_ROLES = ['building_inspector', 'electrical_inspector', 'mechanical_inspector', ...EXECUTIVE_ROLES];
export const FIELD_ROLES     = ['project_engineer', 'construction_foreman', 'field_worker', 'dispatcher', ...SENIOR_ROLES];
export const PROCUREMENT_ROLES = ['project_engineer', 'admin_officer', 'estimator', ...EXECUTIVE_ROLES];
export const ADMIN_ONLY      = ['system_admin', 'manager'];

// ─────────────────────────────────────────────────────────────────────────────
// Unauthorized page
// ─────────────────────────────────────────────────────────────────────────────
const ROLE_LABELS = {
    city_engineer: 'City Engineer',
    asst_city_engineer: 'Assistant City Engineer',
    admin_officer: 'Administrative Officer V',
    admin_clerk: 'Administrative Clerk',
    records_officer: 'Records Officer',
    division_chief: 'Division Chief',
    design_engineer: 'Design Engineer',
    estimator: 'Estimator / QS',
    cad_operator: 'CAD Operator',
    project_engineer: 'Project Engineer',
    construction_foreman: 'Construction Foreman',
    field_worker: 'Field Worker',
    building_inspector: 'Building Inspector',
    electrical_inspector: 'Electrical Inspector',
    mechanical_inspector: 'Mechanical Inspector',
    dispatcher: 'Dispatcher',
    manager: 'Manager',
    system_admin: 'System Administrator',
    resident: 'Resident',
};

const UnauthorizedPage = ({ userRole, allowedRoles }) => {
    const handleSignOut = () => {
        const user = JSON.parse(localStorage.getItem('pulso_user') || '{}');
        const wasGov = user?.role && user.role !== 'resident';
        localStorage.removeItem('pulso_token');
        localStorage.removeItem('pulso_user');
        window.location.href = wasGov ? '/gov' : '/login';
    };

    return (
        <div className="min-h-screen bg-slate-950 flex items-center justify-center p-6">
            <div className="max-w-md w-full text-center space-y-6">
                {/* Icon */}
                <div className="w-20 h-20 bg-red-500/10 border border-red-500/20 rounded-2xl flex items-center justify-center mx-auto">
                    <ShieldX size={40} className="text-red-500" />
                </div>

                {/* Heading */}
                <div>
                    <h1 className="text-2xl font-black text-white mb-2">Access Restricted</h1>
                    <p className="text-slate-400 text-sm leading-relaxed">
                        Your current role{' '}
                        <span className="inline-block px-2 py-0.5 bg-slate-800 text-slate-300 rounded-lg font-bold text-xs mx-1">
                            {ROLE_LABELS[userRole] || userRole}
                        </span>{' '}
                        does not have permission to view this page.
                    </p>
                </div>

                {/* Allowed roles hint */}
                {allowedRoles && allowedRoles.length > 0 && (
                    <div className="bg-slate-900 border border-slate-800 rounded-xl p-4 text-left">
                        <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Required Position</p>
                        <div className="flex flex-wrap gap-1.5">
                            {allowedRoles.map(r => (
                                <span
                                    key={r}
                                    className="px-2 py-0.5 bg-indigo-500/10 text-indigo-400 border border-indigo-500/20 rounded-lg text-xs font-bold"
                                >
                                    {ROLE_LABELS[r] || r}
                                </span>
                            ))}
                        </div>
                    </div>
                )}

                {/* Actions */}
                <div className="flex gap-3 justify-center">
                    <button
                        onClick={() => window.history.back()}
                        className="flex items-center gap-2 px-4 py-2.5 bg-slate-800 hover:bg-slate-700 text-white rounded-xl font-bold text-sm transition-colors"
                    >
                        <ChevronLeft size={16} /> Go Back
                    </button>
                    <a
                        href="/gov/my-dashboard"
                        className="flex items-center gap-2 px-4 py-2.5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl font-bold text-sm transition-colors"
                    >
                        My Dashboard
                    </a>
                    <button
                        onClick={handleSignOut}
                        className="flex items-center gap-2 px-4 py-2.5 bg-red-900/30 hover:bg-red-900/50 border border-red-800/50 text-red-400 rounded-xl font-bold text-sm transition-colors"
                    >
                        <LogOut size={16} /> Sign Out
                    </button>
                </div>
            </div>
        </div>
    );
};

// ─────────────────────────────────────────────────────────────────────────────
// ProtectedRoute gate
// ─────────────────────────────────────────────────────────────────────────────
const ProtectedRoute = ({ children, allowedRoles = null, requiredPermission = null }) => {
    const location = useLocation();

    // Read auth state
    const token = localStorage.getItem('pulso_token');
    let user = null;
    try { user = JSON.parse(localStorage.getItem('pulso_user')); } catch {}

    // Not authenticated → to login or gov portal depending on allowedRoles
    if (!token || !user) {
        const isGovRoute = allowedRoles !== null && !allowedRoles.includes('resident');
        const redirectPath = isGovRoute ? '/gov' : '/login';
        return <Navigate to={redirectPath} state={{ from: location }} replace />;
    }

    // Role check — if allowedRoles is null, any authenticated user is OK
    if (allowedRoles !== null && !allowedRoles.includes(user.role)) {
        return <UnauthorizedPage userRole={user.role} allowedRoles={allowedRoles} />;
    }

    // Dynamic Permission check
    if (requiredPermission && !checkPermission(user, requiredPermission.module, requiredPermission.action)) {
        return <UnauthorizedPage userRole={user.role} allowedRoles={null} />; // Or a specialized "No Capability" page
    }

    return children;
};

