                                                    options={polygonOptions}
                                                    onClick={() => {
                                                        setBrgyModalData({ name: displayName, sector, brgyNum });
                                                        setIsBrgyModalOpen(true);
                                                    }}
                                                />
                                            )}
                                        </React.Fragment>
