                                        pixelOffset: new window.google.maps.Size(0, -35),
                                        zIndex: 1000 
                                    }}
                                >
                                    {/* Restore Previous Professional Design */}
                                    <div 
                                        onMouseDown={(e) => e.stopPropagation()}
                                        onClick={(e) => e.stopPropagation()}
