                                            background: systemIsDark ? 'linear-gradient(160deg,#0f172a 0%,#1e293b 100%)' : '#ffffff', 
                                            borderRadius:'16px', 
                                            padding:'16px', 
                                            minWidth:'220px', 
                                            border: systemIsDark ? '1px solid rgba(255,255,255,0.07)' : '1px solid #e2e8f0', 
