                                                        style={{ 
                                                            width:'100%', 
                                                            padding:'10px 0', 
                                                            background: directionsLoading 
                                                                ? (systemIsDark ? 'rgba(255,255,255,0.02)' : 'rgba(0,0,0,0.02)') 
