                                                    value={newRecordForm.priority || 'low'} 
                                                    onChange={v => setNewRecordForm({...newRecordForm, priority: v})} 
                                                    options={[
                                                        {value:'low',label:'Low'},
                                                        {value:'medium',label:'Medium'},
                                                        {value:'high',label:'High'},
                                                        {value:'emergency',label:'Emergency'}
