                        <button onClick={() => changeTheme('system')} className={`p-2 rounded-full transition-all ${theme === 'system' ? 'bg-white dark:bg-slate-700 shadow-md text-orange-500 scale-110' : 'text-slate-400 hover:text-slate-600 dark:hover:text-slate-200'}`}><Monitor size={14} /></button>
                        <button onClick={() => changeTheme('dark')} className={`p-2 rounded-full transition-all ${theme === 'dark' ? 'bg-white dark:bg-slate-700 shadow-md text-orange-500 scale-110' : 'text-slate-400 hover:text-slate-600 dark:hover:text-slate-200'}`}><Moon size={14} /></button>
                    </div>
                </div>
            </nav>

            {/* ── Main Content Grid ─────── */}
            <main className="relative z-10 grid lg:grid-cols-12 min-h-screen items-center pt-28 pb-32 px-6 lg:px-12 xl:px-24 w-full gap-8">
                
                {/* Left: Hero Text */}
                <div className="lg:col-span-5 text-center lg:text-left mb-8 lg:mb-0 max-w-2xl mx-auto lg:mx-0">
                    <motion.div initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }} transition={{ duration: 0.8 }}>
                        <div className="flex items-center justify-center lg:justify-start gap-2 mb-4 text-orange-600 dark:text-orange-500">
                            <User size={18} />
                            <span className="text-sm font-bold tracking-[0.3em] uppercase">Join The Network</span>
                        </div>
                        <h1 className="text-4xl sm:text-5xl md:text-6xl font-black text-slate-900 dark:text-white leading-[1.1] mb-6 tracking-tighter">
                            BECOME THE <span className="text-transparent bg-clip-text bg-gradient-to-r from-orange-500 to-orange-600">EYES & EARS</span>
                        </h1>
                        <p className="text-sm md:text-base text-slate-600 dark:text-slate-400 font-medium max-w-lg mx-auto lg:mx-0">
                            Sign up to gain access to the resident dashboard. Report incidents, track local hazards, and collaborate with your community.
                        </p>
                    </motion.div>
                </div>

                {/* Right: Registration Panel (Landscape-oriented form) */}
                <div className="lg:col-span-7 w-full max-w-2xl lg:max-w-none mx-auto lg:pl-4">
                    <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} transition={{ duration: 0.8, delay: 0.2 }}>
                        <div className="relative group">
                            <div className="absolute -inset-1 bg-gradient-to-r from-orange-600/20 to-blue-600/20 rounded-[2rem] blur-xl opacity-30 dark:opacity-40 group-hover:opacity-60 transition duration-1000" />
                            <div className="relative bg-white/60 dark:bg-slate-900/60 backdrop-blur-xl border border-white/40 dark:border-white/10 rounded-[2rem] p-6 lg:p-10 shadow-2xl min-h-[400px] flex flex-col justify-center">
                    {/* Stepper */}
                    <div className="flex items-center mb-6 relative px-1">
                        <div className="absolute top-1/2 left-0 w-full h-0.5 bg-slate-200 dark:bg-slate-700 -translate-y-1/2 z-0 rounded-full" />
                        <div className={`absolute top-1/2 left-0 h-0.5 bg-orange-500 -translate-y-1/2 z-0 rounded-full transition-all duration-500 ${step === 1 ? 'w-0' : step === 2 ? 'w-1/3' : step === 3 ? 'w-2/3' : 'w-full'}`} />
                        {[1, 2, 3, 4].map(s => (
                            <div key={s} className={`relative z-10 flex items-center justify-center w-9 h-9 rounded-full font-bold text-sm border-2 transition-all duration-300 mr-auto last:mr-0
                                ${step > s ? 'bg-orange-500 border-orange-500 text-white shadow-md' :
                                  step === s ? 'bg-orange-500 border-orange-500 text-white shadow-lg ring-4 ring-orange-200 dark:ring-orange-900' :
                                  'bg-white dark:bg-slate-900 border-slate-300 dark:border-slate-600 text-slate-400'}`}>
                                {step > s ? <CheckCircle size={16} /> : s}
                            </div>
                        ))}
                    </div>

                    {/* Step title */}
                    <div className="mb-5">
                        <h2 className="text-xl font-black text-slate-900 dark:text-white">
                            {step === 1 && 'Identity Verification'}
                            {step === 2 && 'Personal Information'}
                            {step === 3 && 'Account Credentials'}
                            {step === 4 && 'Account Verification'}
                            {step === 5 && 'Registration Complete!'}
                        </h2>
                        <p className="text-sm text-slate-500 dark:text-slate-400 mt-0.5">
                            {step === 1 && 'Upload a valid Philippine government-issued ID to auto-fill your details.'}
                            {step === 2 && 'Review and complete your personal information.'}
                            {step === 3 && 'Set up your login credentials.'}
                            {step === 4 && 'Enter the 6-digit code sent to your email.'}
                        </p>
                    </div>

                    <AnimatePresence mode="wait">
                        {/* ── STEP 1: ID Upload ── */}
                        {step === 1 && (
                            <motion.div key="s1" initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -20 }} transition={{ duration: 0.3 }}>
                                <div className="grid grid-cols-2 gap-3 mb-4">
                                    {/* Front */}
                                    <div className="relative group aspect-[1.58/1] w-full rounded-2xl overflow-hidden bg-slate-100/50 dark:bg-slate-900/40 border border-slate-200 dark:border-white/10 shadow-inner">
                                        <input type="file" id="idFront" accept="image/*" onChange={e => handleFileUpload(e, 'idFront')} className="hidden" />
                                        <label htmlFor="idFront" className={`flex flex-col items-center justify-center w-full h-full border-2 border-dashed rounded-2xl cursor-pointer transition-all relative
                                            ${formData.idFront ? 'border-green-400 bg-green-50/30 dark:bg-green-900/10' : 'border-slate-300 dark:border-slate-600 hover:border-orange-400 bg-transparent'}`}>
                                            {previews.front ? (
                                                <>
                                                    <motion.div 
                                                        animate={isScanning ? { rotateY: [0, 180, 360], rotateZ: formData.idFrontRotation } : { rotateZ: formData.idFrontRotation }} 
                                                        transition={isScanning ? { rotateY: { duration: 3, repeat: Infinity, ease: "linear" }, rotateZ: { duration: 0.3 } } : { duration: 0.3 }}
                                                        className="absolute inset-0 w-full h-full transform-gpu flex items-center justify-center p-3" 
                                                        style={{ perspective: 1000, transformStyle: 'preserve-3d' }}
                                                    >
                                                        <img src={previews.front} alt="Front" className="max-w-full max-h-full object-contain opacity-90 group-hover:opacity-60 transition-opacity rounded-lg shadow-sm" />
                                                        {isScanning && <div className="absolute inset-2 bg-orange-500/10 mix-blend-overlay rounded-lg" />}
                                                    </motion.div>
                                                    {isScanning && (
                                                        <motion.div 
                                                            className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-orange-400 to-transparent shadow-[0_0_20px_rgba(249,115,22,1)] z-30"
                                                            animate={{ top: ['0%', '100%', '0%'] }}
                                                            transition={{ duration: 2, repeat: Infinity, ease: "linear" }}
                                                        />
                                                    )}
                                                    <button type="button" onClick={e => handleRemoveID(e, 'idFront')} className="absolute top-2 right-2 bg-red-500 hover:bg-red-600 text-white p-1 rounded-full z-20 shadow">
                                                        <X size={14} />
                                                    </button>
                                                    {!isScanning && (
                                                        <div className="absolute inset-0 flex items-center justify-center transition-opacity bg-black/40 cursor-pointer z-10"
                                                             onClick={e => { e.preventDefault(); e.stopPropagation(); setZoomedSide('idFront'); }}>
                                                            <ZoomIn size={28} className="text-white" />
                                                        </div>
                                                    )}
                                                    <div className="absolute bottom-0 left-0 right-0 bg-green-500/90 text-white text-xs font-bold py-1.5 text-center flex items-center justify-center gap-1 z-20">
                                                        <CheckCircle size={12}/> ID Front ✓
                                                    </div>
                                                </>
                                            ) : (
                                                <>
                                                    <div className="flex flex-col items-center justify-center text-center p-4">
                                                        <div className="relative mb-4">
                                                            <div className="absolute inset-0 bg-orange-500/20 blur-xl rounded-full scale-150 opacity-0 group-hover:opacity-100 transition-opacity duration-500" />
                                                            <UploadCloud size={32} className="text-slate-400 group-hover:text-orange-500 relative transition-all duration-300 group-hover:scale-110" />
                                                        </div>
                                                        <span className="text-[11px] font-black text-slate-500 group-hover:text-slate-900 dark:group-hover:text-white transition-colors uppercase tracking-[0.2em] mb-4">ID Front</span>
                                                        <div className="flex gap-2">
                                                            <div className="px-4 py-1.5 bg-slate-100 dark:bg-white/5 border border-slate-200 dark:border-white/10 rounded-full text-[10px] font-black text-slate-600 dark:text-slate-400 uppercase tracking-wider hover:bg-slate-200 dark:hover:bg-white/10 transition-all shadow-sm">
                                                                Upload File
                                                            </div>
                                                            <button 
                                                                onClick={(e) => openCamera(e, 'front')}
                                                                className="px-4 py-1.5 bg-orange-500/10 border border-orange-500/20 rounded-full text-[10px] font-black text-orange-600 dark:text-orange-400 uppercase tracking-wider hover:bg-orange-500 hover:text-white dark:hover:text-white transition-all flex items-center gap-1.5 shadow-sm group/cam"
                                                            >
                                                                <Camera size={12} className="group-hover/cam:scale-110 transition-transform" /> Take Photo
                                                            </button>
                                                        </div>
                                                    </div>
                                                </>
                                            )}
                                        </label>
                                    </div>

                                    {/* Back */}
                                    <div className="relative group aspect-[1.58/1] w-full rounded-2xl overflow-hidden bg-slate-100/50 dark:bg-slate-900/40 border border-slate-200 dark:border-white/10 shadow-inner">
                                        <input type="file" id="idBack" accept="image/*" onChange={e => handleFileUpload(e, 'idBack')} className="hidden" />
                                        <label htmlFor="idBack" className={`flex flex-col items-center justify-center w-full h-full border-2 border-dashed rounded-2xl cursor-pointer transition-all relative
                                            ${formData.idBack ? 'border-green-400 bg-green-50/30 dark:bg-green-900/10' : 'border-slate-300 dark:border-slate-600 hover:border-orange-400 bg-transparent'}`}>
                                            {previews.back ? (
                                                <>
                                                    <motion.div 
                                                        animate={isScanning ? { rotateY: [0, 180, 360], rotateZ: formData.idBackRotation } : { rotateZ: formData.idBackRotation }} 
                                                        transition={isScanning ? { rotateY: { duration: 3, repeat: Infinity, ease: "linear" }, rotateZ: { duration: 0.3 } } : { duration: 0.3 }}
                                                        className="absolute inset-0 w-full h-full transform-gpu flex items-center justify-center p-3" 
                                                        style={{ perspective: 1000, transformStyle: 'preserve-3d' }}
                                                    >
                                                        <img src={previews.back} alt="Back" className="max-w-full max-h-full object-contain opacity-90 group-hover:opacity-60 transition-opacity rounded-lg shadow-sm" />
                                                        {isScanning && <div className="absolute inset-2 bg-orange-500/10 mix-blend-overlay rounded-lg" />}
                                                    </motion.div>
                                                    {isScanning && (
                                                        <motion.div 
                                                            className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-orange-400 to-transparent shadow-[0_0_20px_rgba(249,115,22,1)] z-30"
                                                            animate={{ top: ['0%', '100%', '0%'] }}
                                                            transition={{ duration: 2, repeat: Infinity, ease: "linear" }}
                                                        />
                                                    )}
                                                    <button type="button" onClick={e => handleRemoveID(e, 'idBack')} className="absolute top-2 right-2 bg-red-500 hover:bg-red-600 text-white p-1 rounded-full z-20 shadow">
                                                        <X size={14} />
                                                    </button>
                                                    {!isScanning && (
                                                        <div className="absolute inset-0 flex items-center justify-center transition-opacity bg-black/40 cursor-pointer z-10"
                                                             onClick={e => { e.preventDefault(); e.stopPropagation(); setZoomedSide('idBack'); }}>
                                                            <ZoomIn size={28} className="text-white" />
                                                        </div>
                                                    )}
                                                    <div className="absolute bottom-0 left-0 right-0 bg-green-500/90 text-white text-xs font-bold py-1.5 text-center flex items-center justify-center gap-1 z-20">
                                                        <CheckCircle size={12}/> ID Back ✓
                                                    </div>
                                                </>
                                            ) : (
                                                <>
                                                    <div className="flex flex-col items-center justify-center text-center p-4">
                                                        <div className="relative mb-4">
                                                            <div className="absolute inset-0 bg-orange-500/20 blur-xl rounded-full scale-150 opacity-0 group-hover:opacity-100 transition-opacity duration-500" />
                                                            <UploadCloud size={32} className="text-slate-400 group-hover:text-orange-500 relative transition-all duration-300 group-hover:scale-110" />
                                                        </div>
                                                        <span className="text-[11px] font-black text-slate-500 group-hover:text-slate-900 dark:group-hover:text-white transition-colors uppercase tracking-[0.2em] mb-4">ID Back</span>
                                                        <div className="flex gap-2">
                                                            <div className="px-4 py-1.5 bg-slate-100 dark:bg-white/5 border border-slate-200 dark:border-white/10 rounded-full text-[10px] font-black text-slate-600 dark:text-slate-400 uppercase tracking-wider hover:bg-slate-200 dark:hover:bg-white/10 transition-all shadow-sm">
                                                                Upload File
                                                            </div>
                                                            <button 
                                                                onClick={(e) => openCamera(e, 'back')}
                                                                className="px-4 py-1.5 bg-orange-500/10 border border-orange-500/20 rounded-full text-[10px] font-black text-orange-600 dark:text-orange-400 uppercase tracking-wider hover:bg-orange-500 hover:text-white dark:hover:text-white transition-all flex items-center gap-1.5 shadow-sm group/cam"
                                                            >
                                                                <Camera size={12} className="group-hover/cam:scale-110 transition-transform" /> Take Photo
                                                            </button>
                                                        </div>
                                                    </div>
                                                </>
                                            )}
                                        </label>
                                    </div>
                                </div>

                                {/* Tips */}
                                <div className="bg-blue-50 dark:bg-blue-900/20 border border-blue-100 dark:border-blue-800/50 rounded-xl p-3 mb-4 text-xs text-blue-700 dark:text-blue-400">
                                    <strong>Tips for best results:</strong> Lay ID on a flat surface with good lighting. Avoid glare and shadows. Ensure all text is clearly readable.
                                </div>

                                {/* Error */}
                                {scanError && (
                                    <div className="mb-4 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-xl p-3 flex gap-2 items-start text-sm text-red-700 dark:text-red-400">
                                        <AlertCircle size={16} className="shrink-0 mt-0.5" />
                                        <span>{scanError}</span>
                                    </div>
                                )}

                                <div className="space-y-4 mb-4">
                                    {/* Verification Disclaimer */}
                                    <div className="flex gap-3 items-start p-3 bg-slate-100/50 dark:bg-white/5 rounded-xl border border-slate-200 dark:border-white/10 shadow-sm transition-colors hover:bg-slate-100 dark:hover:bg-white/[0.08]">
                                        <div className="w-8 h-8 rounded-lg bg-orange-500/10 flex items-center justify-center shrink-0">
                                            <Info size={16} className="text-orange-500" />
                                        </div>
                                        <div className="flex-1">
                                            <p className="text-[10px] font-black text-slate-900 dark:text-white uppercase tracking-widest mb-0.5">Verification Disclaimer</p>
                                            <p className="text-[11px] text-slate-500 dark:text-slate-400 leading-relaxed font-bold">Please double check all extracted details after the biometric ID scan. You are responsible for ensuring the accuracy of your personal information before final submission.</p>
                                        </div>
                                    </div>

                                    {/* Terms and Conditions Checkbox */}
                                    <label className="flex items-center gap-3 cursor-pointer group select-none px-1">
                                        <div className="relative">
                                            <input 
                                                type="checkbox" 
                                                checked={agreedToTerms}
                                                onChange={(e) => setAgreedToTerms(e.target.checked)}
                                                className="sr-only peer" 
                                            />
                                            <div className="w-5 h-5 border-2 border-slate-300 dark:border-slate-600 rounded-lg bg-white/50 dark:bg-slate-900/50 transition-all peer-checked:bg-orange-500 peer-checked:border-orange-500 flex items-center justify-center peer-focus:ring-2 peer-focus:ring-orange-500/30">
                                                <div className={`transition-all duration-300 ${agreedToTerms ? 'opacity-100 scale-100' : 'opacity-0 scale-50'}`}>
                                                    <div className="w-1.5 h-3 border-r-2 border-b-2 border-white rotate-45 mb-1" />
                                                </div>
                                            </div>
                                        </div>
                                        <span className="text-[11px] text-slate-500 dark:text-slate-400 group-hover:text-slate-700 dark:group-hover:text-slate-300 transition-colors font-bold leading-tight">
                                            I agree to the <button type="button" onClick={() => { setTermsModalType('terms'); setIsTermsModalOpen(true); }} className="text-orange-500 hover:text-orange-600 underline">Terms of Service</button> and <button type="button" onClick={() => { setTermsModalType('privacy'); setIsTermsModalOpen(true); }} className="text-orange-500 hover:text-orange-600 underline">Privacy Policy</button>
                                        </span>
                                    </label>
                                </div>

                                <div className="flex flex-col gap-3">
                                    <button
                                        type="button"
                                        onClick={handleScanID}
                                        disabled={!formData.idFront || !formData.idBack || isScanning || !agreedToTerms}
                                        className="w-full bg-gradient-to-r from-orange-500 to-orange-400 hover:from-orange-600 hover:to-orange-500 text-white py-3.5 rounded-2xl font-bold text-sm transition-all shadow-md disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 group/btn"
                                    >
                                        {isScanning ? (
                                            <><Loader2 size={18} className="animate-spin" /> Identifying ID Side & Type...</>
                                        ) : (
                                            <>
                                                <ShieldCheck size={18} className="group-hover/btn:scale-110 transition-transform" /> 
                                                Scan Documents & Continue
                                            </>
                                        )}
                                    </button>
                                    <p className="text-[10px] text-center font-bold text-slate-400 uppercase tracking-widest">Both Front and Back required for maximum AI accuracy</p>
                                </div>
                            </motion.div>
                        )}

                        {/* ── STEP 2: Personal Info ── */}
                        {step === 2 && (
                            <motion.div key="s2" initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -20 }} transition={{ duration: 0.3 }}>
                                {/* Verification badge */}
                                {verifiedBadge && (
                                    <div className="mb-4 bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-800 rounded-xl p-3 flex gap-3 items-center justify-between">
                                        <div className="flex items-center gap-3">
                                            <div className="w-8 h-8 bg-green-500/10 text-green-600 rounded-full flex items-center justify-center shrink-0">
                                                <ShieldCheck size={18} />
                                            </div>
                                            <div>
                                                <p className="font-bold text-green-700 dark:text-green-400 text-xs">Identity Verified via AI</p>
                                                <p className="text-[11px] text-green-600/80 dark:text-green-500/70">Intelligence Parse Complete. Please review your details below.</p>
                                            </div>
                                        </div>
                                        {formData.idType && formData.idType !== 'Unknown Document' && (
                                            <div className="shrink-0 flex items-center gap-1.5 px-3 py-1 bg-green-500/20 text-green-400 border border-green-500/30 rounded-lg">
                                                <span className="text-[10px] font-black uppercase tracking-widest">{formData.idType}</span>
                                            </div>
                                        )}
                                    </div>
                                )}

                                {/* Required Fields Legend */}
                                <div className="flex items-center gap-1.5 mb-2 px-1 text-xs text-slate-500 dark:text-slate-400 font-medium">
                                    <span className="text-red-500 font-black text-sm">*</span> Indicates a required field
                                </div>

                                {/* Full Name */}
                                <SectionHeading>Full Name</SectionHeading>
                                <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
                                    <InputField label="First Name" name="firstName" value={formData.firstName} onChange={handleChange} required />
                                    <InputField label="Middle Name" name="middleName" value={formData.middleName} onChange={handleChange} placeholder="Optional" />
                                    <InputField label="Last Name" name="lastName" value={formData.lastName} onChange={handleChange} required />
                                    <InputField label="Suffix" name="suffix" value={formData.suffix} onChange={handleChange} placeholder="e.g. Jr." />
                                </div>

                                {/* Demographics */}
                                <SectionHeading>Demographics</SectionHeading>
                                <div className="grid grid-cols-3 gap-2">
                                    <CustomDatePicker 
                                        label="Date of Birth"
                                        name="dob"
                                        value={formData.dob} 
                                        onChange={handleChange} 
                                        required 
                                    />
                                    <InputField label="Age" name="age" value={formData.age} onChange={handleChange} readOnly placeholder="Auto-filled" />
                                    <CustomSelect label="Sex" name="sex" value={formData.sex} onChange={handleChange} options={['Male', 'Female']} required />
                                </div>

                                <AnimatePresence>
                                    {ageError && (
                                        <motion.div
                                            initial={{ opacity: 0, height: 0 }}
                                            animate={{ opacity: 1, height: 'auto' }}
                                            exit={{ opacity: 0, height: 0 }}
                                            className="mt-4 p-3 bg-red-500/10 border border-red-500/20 rounded-xl flex items-center gap-3"
                                        >
                                            <div className="w-2 h-2 rounded-full bg-red-500 animate-pulse shrink-0" />
                                            <p className="text-xs font-bold text-red-500">{ageError}</p>
                                        </motion.div>
                                    )}
                                </AnimatePresence>

                                {/* Address */}
                                <SectionHeading>Complete Address</SectionHeading>
                                <div className="grid grid-cols-2 md:grid-cols-3 gap-2">
                                    <InputField label="House Number / Floor / Unit" name="houseNo" value={formData.houseNo} onChange={handleChange} />
                                    <InputField label="Block & Lot" name="blockLot" value={formData.blockLot} onChange={handleChange} />
                                    <InputField label="Building / Subdivision / Village" name="subdivision" value={formData.subdivision} onChange={handleChange} className="col-span-2 md:col-span-1" />
                                    <InputField label="Street / Avenue / Corner / Road" name="street" value={formData.street} onChange={handleChange} className="col-span-2" />
                                    <CustomSelect label="Barangay" name="barangay" value={formData.barangay} onChange={handleChange} options={Array.from({ length: 24 }, (_, i) => `Barangay ${165 + i}`)} required />
                                    <InputField label="City" name="municipality" value={formData.municipality} onChange={handleChange} readOnly />
                                    <InputField label="Province" name="province" value={formData.province} onChange={handleChange} readOnly />
                                    <div className="relative">
                                        <div className="flex items-center gap-1 mb-1.5 pl-0.5">
                                            <label className="block text-xs font-bold text-slate-500 dark:text-slate-400">Postal Code</label>
                                            <div className="relative flex items-center justify-center">
                                                <Info size={13} className="peer text-slate-400 cursor-help hover:text-orange-500 transition-colors" />
                                                <div className="absolute bottom-full mb-2 left-1/2 -translate-x-1/2 bg-slate-800 dark:bg-slate-700 text-white text-[11px] font-medium rounded-lg py-1.5 px-3 opacity-0 peer-hover:opacity-100 transition-opacity pointer-events-none whitespace-nowrap z-50 shadow-lg">
                                                    {formData.barangay ? `Postal code for ${formData.barangay}` : 'Select a barangay to auto-fill'}
                                                    <div className="absolute top-full left-1/2 -translate-x-1/2 border-[5px] border-transparent border-t-slate-800 dark:border-t-slate-700"></div>
                                                </div>
                                            </div>
                                        </div>
                                        <input
                                            type="text"
                                            name="postalCode"
                                            value={formData.postalCode}
                                            readOnly
                                            placeholder="Auto-filled"
                                            className="w-full border text-sm rounded-xl px-3 py-2.5 outline-none transition-all bg-slate-100 dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-400 cursor-not-allowed font-medium"
                                        />
                                    </div>
                                </div>

                                <div className="flex gap-3 mt-5">
                                    <button type="button" onClick={prevStep} className="w-1/3 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-300 py-3 rounded-2xl font-bold text-sm transition-all">Back</button>
                                    <button
                                        type="button"
                                        onClick={nextStep}
                                        disabled={!step2Valid}
                                        className="w-2/3 bg-orange-500 hover:bg-orange-600 text-white py-3 rounded-2xl font-bold text-sm transition-all shadow-md disabled:opacity-50 disabled:cursor-not-allowed"
                                    >
                                        Next Step
                                    </button>
                                </div>
                            </motion.div>
                        )}

                        {/* ── STEP 3: Account Credentials ── */}
                        {step === 3 && (
                            <motion.div key="s3" initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -20 }} transition={{ duration: 0.3 }}>
                                <form onSubmit={handleSubmit}>
                                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 mb-3">
                                        <div>
                                            <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1.5 pl-0.5">Email Address <span className="text-red-400">*</span></label>
                                            <div className="relative">
                                                <Mail size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
                                                <input type="email" name="email" value={formData.email} onChange={handleChange} placeholder="you@email.com" required
                                                    className="w-full bg-white dark:bg-slate-800/60 border border-slate-200 dark:border-slate-700 text-slate-900 dark:text-white placeholder-slate-400 text-sm rounded-xl pl-9 pr-3 py-2.5 focus:ring-2 focus:ring-orange-500 outline-none transition-all" />
                                            </div>
                                        </div>
                                        <div>
                                            <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1.5 pl-0.5">Mobile Number <span className="text-red-400">*</span></label>
                                            <div className="relative">
                                                <Phone size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
                                                <input type="tel" name="mobile" value={formData.mobile} onChange={handleChange} placeholder="09XXXXXXXXX" required
                                                    className="w-full bg-white dark:bg-slate-800/60 border border-slate-200 dark:border-slate-700 text-slate-900 dark:text-white placeholder-slate-400 text-sm rounded-xl pl-9 pr-3 py-2.5 focus:ring-2 focus:ring-orange-500 outline-none transition-all" />
                                            </div>
                                        </div>
                                        <div>
                                            <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1.5 pl-0.5">Password <span className="text-red-400">*</span></label>
                                            <div className="relative">
                                                <Lock size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
                                                <input type={showPassword ? "text" : "password"} name="password" value={formData.password} onChange={handleChange} placeholder="Min. 8 characters" required minLength={8}
                                                    className="w-full bg-white dark:bg-slate-800/60 border border-slate-200 dark:border-slate-700 text-slate-900 dark:text-white placeholder-slate-400 text-sm rounded-xl pl-9 pr-10 py-2.5 focus:ring-2 focus:ring-orange-500 outline-none transition-all" />
                                                <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-orange-500 transition-colors focus:outline-none" aria-label={showPassword ? "Hide password" : "Show password"}>
                                                    {showPassword ? <EyeOff size={15} /> : <Eye size={15} />}
                                                </button>
                                            </div>

                                            {/* Password Strength Meter */}
                                            {formData.password && (
                                                <div className="mt-2 space-y-2 px-1">
                                                    <div className="flex justify-between items-center text-[9px] font-black uppercase tracking-widest">
                                                        <span className="text-slate-400">Security Strength</span>
                                                        <span className={
                                                            formData.password.length < 8 || !/[A-Z]/.test(formData.password) || !/[0-9]/.test(formData.password) || !/[^A-Za-z0-9]/.test(formData.password)
                                                                ? (formData.password.length < 8 ? "text-red-500" : "text-orange-500")
                                                                : "text-green-500"
                                                        }>
                                                            {formData.password.length < 8 ? "Weak" : (
                                                                !/[A-Z]/.test(formData.password) || !/[0-9]/.test(formData.password) || !/[^A-Za-z0-9]/.test(formData.password)
                                                                    ? "Medium"
                                                                    : "Strong"
                                                            )}
                                                        </span>
                                                    </div>
                                                    <div className="h-1 w-full bg-slate-100 dark:bg-white/5 rounded-full overflow-hidden flex gap-1">
                                                        <div className={`h-full transition-all duration-500 rounded-full ${formData.password.length >= 8 ? 'bg-orange-500 w-1/4' : 'bg-red-500 w-1/4'}`} />
                                                        <div className={`h-full transition-all duration-500 rounded-full ${/[A-Z]/.test(formData.password) ? 'bg-orange-500 w-1/4' : 'bg-slate-200 dark:bg-white/5 w-1/4'}`} />
                                                        <div className={`h-full transition-all duration-500 rounded-full ${/[0-9]/.test(formData.password) ? 'bg-orange-500 w-1/4' : 'bg-slate-200 dark:bg-white/5 w-1/4'}`} />
                                                        <div className={`h-full transition-all duration-500 rounded-full ${/[^A-Za-z0-9]/.test(formData.password) ? 'bg-green-500 w-1/4' : 'bg-slate-200 dark:bg-white/5 w-1/4'}`} />
                                                    </div>
                                                    <div className="flex flex-wrap gap-2 pt-1 uppercase">
                                                        <span className={`text-[8px] font-bold px-1.5 py-0.5 rounded border transition-all ${formData.password.length >= 8 ? 'bg-green-500/10 border-green-500/20 text-green-500' : 'bg-slate-100 dark:bg-white/5 border-slate-200 dark:border-white/10 text-slate-400 opacity-50'}`}>8+ Chars</span>
                                                        <span className={`text-[8px] font-bold px-1.5 py-0.5 rounded border transition-all ${/[A-Z]/.test(formData.password) ? 'bg-green-500/10 border-green-500/20 text-green-500' : 'bg-slate-100 dark:bg-white/5 border-slate-200 dark:border-white/10 text-slate-400 opacity-50'}`}>Capital</span>
                                                        <span className={`text-[8px] font-bold px-1.5 py-0.5 rounded border transition-all ${/[0-9]/.test(formData.password) ? 'bg-green-500/10 border-green-500/20 text-green-500' : 'bg-slate-100 dark:bg-white/5 border-slate-200 dark:border-white/10 text-slate-400 opacity-50'}`}>Number</span>
                                                        <span className={`text-[8px] font-bold px-1.5 py-0.5 rounded border transition-all ${/[^A-Za-z0-9]/.test(formData.password) ? 'bg-green-500/10 border-green-500/20 text-green-500' : 'bg-slate-100 dark:bg-white/5 border-slate-200 dark:border-white/10 text-slate-400 opacity-50'}`}>Special</span>
                                                    </div>
                                                </div>
                                            )}
                                        </div>
                                        <div>
                                            <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1.5 pl-0.5">Confirm Password <span className="text-red-400">*</span></label>
                                            <div className="relative">
                                                <Lock size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
                                                <input type={showConfirmPassword ? "text" : "password"} name="confirmPassword" value={formData.confirmPassword} onChange={handleChange} placeholder="Repeat password" required
                                                    className={`w-full bg-white dark:bg-slate-800/60 border text-slate-900 dark:text-white placeholder-slate-400 text-sm rounded-xl pl-9 pr-10 py-2.5 focus:ring-2 focus:ring-orange-500 outline-none transition-all
                                                        ${formData.confirmPassword && formData.password !== formData.confirmPassword
                                                            ? 'border-red-400 focus:ring-red-400'
                                                            : 'border-slate-200 dark:border-slate-700'}`}
                                                />
                                                <button type="button" onClick={() => setShowConfirmPassword(!showConfirmPassword)} className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-orange-500 transition-colors focus:outline-none" aria-label={showConfirmPassword ? "Hide confirm password" : "Show confirm password"}>
                                                    {showConfirmPassword ? <EyeOff size={15} /> : <Eye size={15} />}
                                                </button>
                                            </div>
                                            {formData.confirmPassword && formData.password !== formData.confirmPassword && (
                                                <p className="text-xs text-red-500 mt-1 pl-0.5">Passwords do not match</p>
                                            )}
                                        </div>
                                    </div>

                                    {registrationError && (
                                        <div className="mb-3 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-xl p-3 text-sm text-red-600 dark:text-red-400 flex items-center gap-2">
                                            <AlertCircle size={15} className="shrink-0" />
                                            {registrationError}
                                        </div>
                                    )}

                                    <div className="flex gap-3 mt-4">
                                        <button type="button" onClick={prevStep} className="w-1/3 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-300 py-3 rounded-2xl font-bold text-sm transition-all">Back</button>
                                        <button
                                            type="submit"
                                            disabled={!formData.email || !formData.mobile || !formData.password || formData.password !== formData.confirmPassword || registering}
                                            className="w-2/3 bg-gradient-to-r from-orange-500 to-orange-400 hover:from-orange-600 hover:to-orange-500 text-white py-3 rounded-2xl font-bold text-sm transition-all shadow-md disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                                        >
                                            {registering ? <><Loader2 size={17} className="animate-spin" /> Creating Account...</> : 'Create My Account'}
                                        </button>
                                    </div>
                                </form>
                            </motion.div>
                        )}

                        {/* ── STEP 4: Account Verification ── */}
                        {step === 4 && (
                            <motion.div key="s4" initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -20 }} transition={{ duration: 0.3 }}
                                className="flex flex-col items-center text-center py-4">
                                <div className="mb-6">
                                    <p className="text-sm text-slate-500 dark:text-slate-400 mb-6">
                                        Please enter the code we sent to<br/>
                                        <span className="font-bold text-slate-900 dark:text-white break-all">{formData.email}</span>
                                    </p>
                                    
                                    <div className="flex justify-center gap-2 mb-8">
                                        {otp.map((digit, index) => (
                                            <input
                                                key={index}
                                                ref={otpRefs[index]}
                                                type="text"
                                                maxLength="1"
                                                value={digit}
                                                onChange={(e) => handleOtpChange(index, e.target.value)}
                                                onKeyDown={(e) => handleKeyDown(index, e)}
                                                onPaste={handlePaste}
                                                className="w-12 h-14 text-center text-2xl font-black bg-white dark:bg-slate-800 border-2 border-slate-200 dark:border-slate-700 rounded-2xl focus:border-orange-500 focus:ring-2 focus:ring-orange-500/20 outline-none transition-all text-slate-900 dark:text-white"
                                            />
                                        ))}
                                    </div>
                                    
                                    {verifyError && (
                                        <div className="mb-6 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-xl p-3 text-sm text-red-600 dark:text-red-400 flex items-center justify-center gap-2 text-left">
                                            <AlertCircle size={15} className="shrink-0" />
                                            <span>{verifyError}</span>
                                        </div>
                                    )}
                                    {verifySuccess && (
                                        <motion.div initial={{ opacity: 0, y: -5 }} animate={{ opacity: 1, y: 0 }}
                                            className="mb-6 bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-800 rounded-xl p-3 text-sm text-green-700 dark:text-green-400 flex items-center justify-center gap-2 text-left shadow-sm">
                                            <CheckCircle size={15} className="shrink-0" />
                                            <span>{verifySuccess}</span>
                                        </motion.div>
                                    )}

                                    <button
                                        type="button"
                                        onClick={handleVerifyCode}
                                        disabled={otp.some(d => !d) || verifying}
                                        className="w-full bg-gradient-to-r from-orange-500 to-orange-400 hover:from-orange-600 hover:to-orange-500 text-white py-3.5 rounded-2xl font-bold text-sm transition-all shadow-md disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 mb-6"
                                    >
                                        {verifying ? <><Loader2 size={18} className="animate-spin" /> Verifying...</> : 'Confirm Account'}
                                    </button>

                                    <div className="text-center mt-4">
                                        {resendTimer > 0 ? (
                                            <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest bg-slate-100/50 dark:bg-white/5 py-2 px-4 rounded-full inline-block">
                                                Resend code in <span className="text-orange-600">{resendTimer}s</span>
                                            </p>
                                        ) : (
                                            <p className="text-sm text-slate-500 dark:text-slate-400">
                                                I didn't receive a code!{' '}
                                                <button 
                                                    type="button" 
                                                    onClick={handleResendCode}
                                                    disabled={resending || !canResend}
                                                    className="text-orange-600 dark:text-orange-500 font-bold hover:underline disabled:opacity-50"
                                                >
                                                    {resending ? 'Sending...' : 'Please Resend'}
                                                </button>
                                            </p>
                                        )}
                                    </div>
                                </div>
                            </motion.div>
                        )}

                        {/* ── STEP 5: Success ── */}
                        {step === 5 && (
                            <motion.div key="s5" initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} transition={{ duration: 0.4 }}
                                className="flex flex-col items-center text-center py-6 gap-4">
                                <div className="w-20 h-20 bg-green-100 dark:bg-green-500/20 text-green-500 rounded-full flex items-center justify-center">
                                    <CheckCircle size={40} />
                                </div>
                                <div>
                                    <h3 className="text-2xl font-black text-slate-900 dark:text-white mb-2">Account Verified!</h3>
                                    <p className="text-sm text-slate-500 dark:text-slate-400 max-w-xs">Your PULSO account has been successfully verified. Welcome to the community!</p>
                                </div>
                                <Link to="/login" className="mt-2 bg-gradient-to-r from-orange-500 to-orange-400 hover:from-orange-600 hover:to-orange-500 text-white px-8 py-3.5 rounded-2xl font-bold text-sm transition-all shadow-md flex items-center gap-2">
                                    Proceed to Login
                                </Link>
                            </motion.div>
                        )}
                    </AnimatePresence>

                    {/* Footer link */}
                    {step < 5 && (
                        <div className="mt-8 pt-6 border-t border-slate-200 dark:border-slate-800/50 text-center relative z-20">
                            <p className="text-sm text-slate-600 dark:text-slate-400 font-medium">
                                Already have an account?{' '}
                                <Link to="/login" className="text-orange-600 dark:text-orange-400 font-bold hover:underline decoration-2 underline-offset-4">Sign In</Link>
                            </p>
                        </div>
                    )}
                </div>
            </div>
        </motion.div>
    </div>
</main>

            {/* ── Bottom Info Bar ───────────────── */}
            <div className="absolute bottom-0 left-0 w-full bg-white/60 dark:bg-[#020617]/70 backdrop-blur-md border-t border-slate-200 dark:border-white/5 py-4 px-8 flex flex-col md:flex-row justify-between items-center gap-4 z-50 transition-colors">
                <div className="flex items-center gap-6 overflow-hidden max-w-4xl">
                    <span className="text-[10px] font-black text-orange-600 dark:text-orange-500 uppercase tracking-[0.2em] whitespace-nowrap">Notice:</span>
                    <div className="text-[10px] font-bold text-slate-500 dark:text-slate-600 uppercase tracking-[0.3em] whitespace-nowrap animate-marquee">
                        YOUR PRIVACY IS PROTECTED UNDER THE PHILIPPINE DATA PRIVACY ACT (RA 10173) • AUTHORIZED RESIDENTS ONLY • PULSO CITIZEN PLATFORM • CITY OF CALOOCAN
                    </div>
                </div>
                <div className="flex items-center gap-6 text-[10px] font-black text-slate-400 dark:text-slate-500 tracking-[0.2em]">
                    <span>CALOOCAN NORTH DISTRICT • PHILIPPINES</span>
                    <div className="h-3 w-[1px] bg-slate-200 dark:bg-white/10" />
                    <span className="text-orange-600/50 dark:text-orange-500/50">v4.2.1</span>
                </div>
            </div>

            {/* Zoom modal */}
            <AnimatePresence>
                {zoomedSide && (
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
                        className="fixed inset-0 z-[100] flex items-center justify-center bg-black/80 backdrop-blur-sm p-4 cursor-pointer"
                        onClick={() => setZoomedSide(null)}
                    >
                        <motion.div
                            initial={{ scale: 0.9 }} 
                            animate={{ 
                                scale: 1, 
                                rotate: formData[zoomedSide + 'Rotation'],
                                rotateY: isScanning ? [0, 180, 360] : 0
                            }} 
                            exit={{ scale: 0.9 }} 
                            transition={{ 
                                type: "spring", stiffness: 200, damping: 20,
                                rotateY: isScanning ? { duration: 3, repeat: Infinity, ease: "linear" } : { duration: 0.3 }
                            }}
                            className="relative max-w-full max-h-[80vh] flex items-center justify-center transform-gpu"
                            style={{ perspective: 1000, transformStyle: 'preserve-3d' }}
                            onClick={e => e.stopPropagation()}
                        >
                            <img 
                                src={zoomedSide === 'idFront' ? previews.front : previews.back} 
                                alt="Zoomed document"
                                className="max-w-full max-h-[80vh] object-contain rounded-xl shadow-2xl"
                            />
                            {isScanning && (
                                <>
                                    <div className="absolute inset-0 bg-orange-500/10 mix-blend-overlay rounded-xl" />
                                    <motion.div 
                                        className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-orange-400 to-transparent shadow-[0_0_20px_rgba(249,115,22,1)] z-30"
                                        animate={{ top: ['0%', '100%', '0%'] }}
                                        transition={{ duration: 2, repeat: Infinity, ease: "linear" }}
                                    />
                                </>
                            )}
                        </motion.div>
                        
                        {/* Top Right Controls */}
                        <div className="absolute top-5 right-5 flex items-center gap-3">
                            {/* Scan once: show button only if not yet scanned & not currently scanning */}
                            {!hasScanned && !isScanning && (
                                <button 
                                    className="flex items-center gap-2 px-4 py-2.5 rounded-full font-bold text-sm bg-orange-500 hover:bg-orange-600 text-white transition-all shadow-lg active:scale-95"
                                    onClick={e => { e.stopPropagation(); handleScanID(false); }}
                                >
                                    <ShieldCheck size={16} /> Scan Document
                                </button>
                            )}
                            {isScanning && (
                                <button disabled className="flex items-center gap-2 px-6 py-2.5 rounded-full font-bold text-sm bg-orange-500/20 text-orange-400 cursor-not-allowed shadow-xl border border-orange-500/20">
                                    <Loader2 size={16} className="animate-spin" /> {scanStatus}
                                </button>
                            )}
                            {hasScanned && !isScanning && (
                                <span className="flex items-center gap-2 px-4 py-2.5 rounded-full font-bold text-sm bg-green-500/20 text-green-400 border border-green-500/30 shadow-lg">
                                    <CheckCircle size={16} /> Scanned
                                </span>
                            )}
                            <button className="text-white bg-black/50 hover:bg-black/70 p-3 rounded-full transition-transform hover:scale-105 active:scale-95 shadow-lg" 
                                    onClick={e => { 
                                        e.stopPropagation(); 
                                        const side = zoomedSide;
                                        setFormData(prev => ({ ...prev, [side + 'Rotation']: (prev[side + 'Rotation'] || 0) + 90 }));
                                    }}>
                                <RotateCw size={22} />
                            </button>
                            <button className="text-white bg-red-500/80 hover:bg-red-600 p-3 rounded-full transition-transform hover:scale-105 active:scale-95 shadow-lg" 
                                    onClick={() => setZoomedSide(null)}>
                                <X size={22} />
                            </button>
                        </div>


                    </motion.div>
                )}
            </AnimatePresence>

            {/* Camera Overlay */}
            <IDCameraModal 
                isOpen={cameraOpen}
                onClose={() => setCameraOpen(false)}
                onCapture={handleCameraCapture}
                side={activeCameraSide}
            />

            <AnimatePresence>
                {isTermsModalOpen && (
                    <TermsModal 
                        isOpen={isTermsModalOpen} 
                        onClose={() => setIsTermsModalOpen(false)} 
                        type={termsModalType} 
                    />
                )}
            </AnimatePresence>
        </div>
    );
}

import React, { useState, useEffect } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { 
    ShieldAlert, Lock, ShieldCheck, ArrowLeft, Loader2, 
    CheckCircle2, AlertCircle, Activity, Shield, KeyRound,
    Eye, EyeOff, Check
} from 'lucide-react';
import { useTheme } from '../contexts/ThemeContext';
import { API_BASE_URL } from '../utils/apiBase';

export default function ResetPassword() {
    const { theme } = useTheme();
    const [searchParams] = useSearchParams();
    const token = searchParams.get('token');
    const navigate = useNavigate();

    const [verifying, setVerifying] = useState(true);
    const [emailHint, setEmailHint] = useState('');
    const [password, setPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [showPassword, setShowPassword] = useState(false);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');
    const [success, setSuccess] = useState(false);

    // Password Validation States
    const validations = {
        minChar: password.length >= 8,
        hasUpper: /[A-Z]/.test(password),
        hasNumber: /[0-9]/.test(password),
        hasSpecial: /[!@#$%^&*(),.?":{}|<>]/.test(password)
    };

    const isPasswordValid = Object.values(validations).every(v => v);

    useEffect(() => {
        const validateToken = async () => {
            if (!token) {
                setError('No security token provided.');
                setVerifying(false);
                return;
            }
            try {
                const response = await fetch(`${API_BASE_URL}/api/auth/verify-token/${token}`);
                if (response.ok) {
                    const data = await response.json();
                    setEmailHint(data.email_hint);
                    setVerifying(false);
                } else {
                    setError('Identity token spent or invalid.');
                    setVerifying(false);
                }
            } catch (err) {
                setError('System connectivity error.');
                setVerifying(false);
            }
        };
        validateToken();
    }, [token]);

    const handleReset = async (e) => {
        e.preventDefault();
        if (!isPasswordValid) return;
        if (password !== confirmPassword) {
            setError('Handshake failed: Keys do not match.');
            return;
        }

        setLoading(true);
        setError('');

        try {
            const apiBase = API_BASE_URL;
            const response = await fetch(`${apiBase}/api/auth/reset-password`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ token, new_password: password })
            });

            if (response.ok) {
                setSuccess(true);
                setTimeout(() => navigate('/login'), 3000);
            } else {
                const data = await response.json();
                setError(data.detail || 'Reset failed. Access denied.');
            }
        } catch (err) {
            setError('Global Network Error.');
        } finally {
            setLoading(false);
        }
    };

    const ValidationItem = ({ fulfilled, text }) => (
        <div className={`flex items-center gap-2 text-[11px] font-bold transition-colors ${fulfilled ? 'text-green-500' : 'text-slate-400 dark:text-slate-500'}`}>
            {fulfilled ? <Check size={12} className="stroke-[3px]" /> : <div className="w-3 h-3 rounded-full border border-slate-300 dark:border-slate-700" />}
            {text}
        </div>
    );

    return (
        <div className={`relative min-h-screen w-full overflow-hidden font-inter transition-colors duration-500 ${theme === 'dark' ? 'bg-[#0f172a] text-white' : 'bg-slate-50 text-slate-900'}`}>
            
            {/* CLEAN CSS BACKGROUND (Subtle Grid & Gradient) */}
            <div className="absolute inset-0 z-0">
                <div className={`absolute inset-0 opacity-[0.4] dark:opacity-[0.2] h-full w-full [background-image:linear-gradient(to_right,#80808012_1px,transparent_1px),linear-gradient(to_bottom,#80808012_1px,transparent_1px)] [background-size:24px_24px]`} />
                <div className="absolute inset-x-0 top-0 h-40 bg-gradient-to-b from-orange-500/10 to-transparent pointer-events-none" />
                <div className="absolute inset-x-0 bottom-0 h-40 bg-gradient-to-t from-orange-500/5 to-transparent pointer-events-none" />
            </div>

            {/* Tactical Content Overlay */}
            <div className="relative z-10 min-h-screen flex items-center justify-center p-6 sm:p-12">
                <div className="max-w-4xl w-full">
                    
                    <AnimatePresence mode="wait">
                        {verifying ? (
                            <motion.div 
                                key="verifying"
                                initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
                                className="flex flex-col items-center bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-[2.5rem] p-16 shadow-2xl text-center space-y-6 mx-auto max-w-md"
                            >
                                <Loader2 className="animate-spin text-orange-500" size={32} />
                                <div className="space-y-1">
                                    <p className="text-[10px] font-black uppercase tracking-[0.3em] text-orange-500">Security Clearance</p>
                                    <p className="text-slate-500 dark:text-slate-400 text-sm font-bold">Verifying identity token...</p>
                                </div>
                            </motion.div>
                        ) : error && !success ? (
                            <motion.div 
                                key="error"
                                initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }}
                                className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-[2.5rem] p-14 lg:p-20 shadow-2xl flex flex-col items-center text-center space-y-8 mx-auto max-w-md"
                            >
                                <div className="w-20 h-20 bg-red-500/10 rounded-3xl flex items-center justify-center text-red-500 border border-red-500/20">
                                    <ShieldAlert size={40} />
                                </div>
                                <div className="space-y-3">
                                    <h2 className="text-3xl font-black tracking-tight leading-none text-red-500">Access Restricted</h2>
                                    <p className="text-slate-500 dark:text-slate-400 text-sm font-bold leading-relaxed">{error}</p>
                                </div>
                                <button onClick={() => navigate('/login')} className="w-full py-4 bg-slate-900 dark:bg-white text-white dark:text-slate-900 rounded-2xl font-black text-xs uppercase tracking-widest transition-all shadow-xl active:scale-95">Return to Login</button>
                            </motion.div>
                        ) : success ? (
                            <motion.div 
                                key="success"
                                initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }}
                                className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-[2.5rem] p-14 lg:p-20 shadow-2xl flex flex-col items-center text-center space-y-8 mx-auto max-w-md"
                            >
                                <div className="w-20 h-20 bg-green-500/10 rounded-3xl flex items-center justify-center text-green-500 border border-green-500/20">
                                    <CheckCircle2 size={40} className="animate-bounce" />
                                </div>
                                <div className="space-y-3">
                                    <h2 className="text-3xl font-black tracking-tight leading-none text-green-600 dark:text-green-500">Protocol Complete</h2>
                                    <p className="text-slate-500 dark:text-slate-400 text-sm font-bold">Credential synchronization successful.</p>
                                </div>
                                <div className="w-full bg-slate-100 dark:bg-white/5 h-1.5 rounded-full overflow-hidden">
                                    <motion.div initial={{ width: 0 }} animate={{ width: "100%" }} transition={{ duration: 3 }} className="h-full bg-green-500" />
                                </div>
                            </motion.div>
                        ) : (
                            <motion.div 
                                key="form"
                                initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }}
                                className="grid lg:grid-cols-[1fr,340px] gap-8"
                            >
                                {/* Left Side: Password Form */}
                                <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-[3rem] p-10 lg:p-14 shadow-2xl relative overflow-hidden">
                                    {/* Subtle Overlay Pattern */}
                                    <div className="absolute inset-0 opacity-[0.03] dark:opacity-[0.02] pointer-events-none [background-image:radial-gradient(#808080_1px,transparent_1px)] [background-size:20px_20px]" />

                                    <div className="relative z-10">
                                        <div className="mb-10 flex items-center justify-between">
                                            <div className="flex flex-col">
                                                <h1 className="text-3xl lg:text-4xl font-black tracking-tight leading-none">Access Recovery</h1>
                                                <div className="flex items-center gap-2 text-orange-600 dark:text-orange-500 mt-1">
                                                    <Activity size={14} />
                                                    <span className="text-[10px] font-black uppercase tracking-widest">Update Authorized Officials Only</span>
                                                </div>
                                            </div>
                                            <div className="px-3 py-1 bg-green-500/10 border border-green-500/20 rounded-full text-[9px] font-black text-green-600 dark:text-green-500 uppercase tracking-widest">Token Verified</div>
                                        </div>

                                        {error && (
                                            <div className="mb-8 p-4 bg-red-500/5 border border-red-500/10 rounded-2xl text-[11px] font-bold text-red-500 flex items-center gap-3">
                                                <AlertCircle size={14} /> {error}
                                            </div>
                                        )}

                                        <form onSubmit={handleReset} className="space-y-8">
                                            <div className="space-y-2 relative">
                                                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">New Access Key</label>
                                                <div className="relative group/input">
                                                    <KeyRound size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within/input:text-orange-500 transition-colors" />
                                                    <input
                                                        type={showPassword ? "text" : "password"}
                                                        value={password}
                                                        onChange={(e) => setPassword(e.target.value)}
                                                        className="w-full bg-slate-50 dark:bg-slate-950/50 border border-slate-200 dark:border-slate-800 text-slate-900 dark:text-white placeholder-slate-400 text-sm rounded-2xl focus:outline-none focus:border-orange-500/50 focus:bg-white dark:focus:bg-slate-950 block pl-12 pr-12 p-5 transition-all shadow-sm"
                                                        placeholder="••••••••"
                                                        required
                                                    />
                                                    <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 hover:text-orange-500 transition-colors">
                                                        {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                                                    </button>
                                                </div>
                                            </div>

                                            <div className="space-y-2">
                                                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Confirm Access Key</label>
                                                <div className="relative group/input">
                                                    <ShieldCheck size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within/input:text-orange-500 transition-colors" />
                                                    <input
                                                        type={showPassword ? "text" : "password"}
                                                        value={confirmPassword}
                                                        onChange={(e) => setConfirmPassword(e.target.value)}
                                                        className="w-full bg-slate-50 dark:bg-slate-950/50 border border-slate-200 dark:border-slate-800 text-slate-900 dark:text-white placeholder-slate-400 text-sm rounded-2xl focus:outline-none focus:border-orange-500/50 focus:bg-white dark:focus:bg-slate-950 block pl-12 p-5 transition-all shadow-sm"
                                                        placeholder="••••••••"
                                                        required
                                                    />
                                                </div>
                                            </div>

                                            <div className="pt-4">
                                                <button
                                                    type="submit"
                                                    disabled={loading || !isPasswordValid}
                                                    className="w-full py-5 bg-slate-900 dark:bg-white text-white dark:text-slate-900 hover:bg-orange-600 dark:hover:bg-orange-500 hover:text-white dark:hover:text-white disabled:bg-slate-100 dark:disabled:bg-slate-800 disabled:text-slate-400 dark:disabled:text-slate-600 rounded-2xl font-black text-xs uppercase tracking-[0.3em] transition-all transform hover:scale-[1.01] active:scale-[0.99] shadow-xl flex items-center justify-center gap-3"
                                                >
                                                    {loading ? <Loader2 className="animate-spin" size={18} /> : 'Confirm Synchronization'}
                                                </button>
                                            </div>

                                            <button type="button" onClick={() => navigate('/login')} className="w-full font-black text-[10px] text-slate-400 hover:text-slate-600 dark:hover:text-slate-300 uppercase tracking-[0.2em] transition-colors">Abort Procedure</button>
                                        </form>
                                    </div>
                                </div>

                                {/* Right Side: Guidelines */}
                                <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-[3rem] p-10 lg:p-12 shadow-2xl flex flex-col items-center relative overflow-hidden">
                                     {/* Subtle Overlay Pattern */}
                                    <div className="absolute inset-0 opacity-[0.03] dark:opacity-[0.02] pointer-events-none [background-image:radial-gradient(#808080_1px,transparent_1px)] [background-size:20px_20px]" />

                                    <div className="w-12 h-12 rounded-2xl bg-orange-500/10 flex items-center justify-center text-orange-600 dark:text-orange-500 mb-6 font-bold text-lg">!</div>
                                    <h3 className="text-xs font-black uppercase tracking-widest text-slate-900 dark:text-white mb-8">Security Guidelines</h3>
                                    
                                    <div className="w-full space-y-5">
                                        <ValidationItem fulfilled={validations.minChar} text="Min 8 Alpha-Numeric Keys" />
                                        <ValidationItem fulfilled={validations.hasUpper} text="Capitalized Identifier (A-Z)" />
                                        <ValidationItem fulfilled={validations.hasNumber} text="System Index Value (0-9)" />
                                        <ValidationItem fulfilled={validations.hasSpecial} text="Security Symbol (@, #, $)" />
                                    </div>

                                    <div className="mt-auto pt-10">
                                        <div className="p-5 bg-slate-50 dark:bg-slate-950/50 rounded-2xl border border-slate-100 dark:border-slate-800 text-center">
                                            <div className="flex items-center justify-center gap-2 mb-3">
                                                <Shield size={14} className="text-indigo-500" />
                                                <span className="text-[10px] font-black uppercase text-indigo-500">Registry Note</span>
                                            </div>
                                            <p className="text-[10px] leading-relaxed text-slate-500 dark:text-slate-400 font-bold uppercase tracking-tighter">
                                                Identity verified as <br /> <span className="text-slate-900 dark:text-white tracking-widest">{emailHint}</span>
                                            </p>
                                        </div>
                                    </div>
                                </div>
                            </motion.div>
                        )}
                    </AnimatePresence>
                </div>
            </div>
        </div>
    );
}

import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { Users, Search, UserCheck, UserX, AlertTriangle, RefreshCw, Mail, Phone, MapPin, ChevronDown, MoreVertical, History, Shield } from 'lucide-react';
import { API_BASE_URL } from '../utils/apiBase';
import { getToken } from '../utils/auth';
import GovSidebar from '../components/GovSidebar';
import GovernmentWorkspaceTabs from '../components/GovernmentWorkspaceTabs';

export default function ResidentAccountManagementPage({ workspace }) {
    const token = getToken();
    const [currentUser] = useState(() => {
        try { return JSON.parse(localStorage.getItem('pulso_user')); } catch { return null; }
    });
    
    const [users, setUsers] = useState([]);
    const [loading, setLoading] = useState(true);
    const [counts, setCounts] = useState({ resident: { active: 0, suspended: 0 }, government: { active: 0, suspended: 0 }, total: 0 });
    
    const [filters, setFilters] = useState({ search: '', status: '' });
    const [pagination, setPagination] = useState({ limit: 50, offset: 0, total: 0 });
    const [selectedUser, setSelectedUser] = useState(null);
    const [actionModal, setActionModal] = useState(null);
    const [actionReason, setActionReason] = useState('');

    const fetchCounts = async () => {
        try {
            const res = await fetch(`${API_BASE_URL}/api/gov/users/stats`, {
                headers: { 'Authorization': `Bearer ${token}` }
            });
            if (res.ok) {
                const data = await res.json();
                setCounts(data);
            }
        } catch (err) {
            console.error('Failed to fetch counts:', err);
        }
    };

    const fetchUsers = async () => {
        setLoading(true);
        try {
            const params = new URLSearchParams();
            params.append('account_type', 'resident');
            if (filters.status) params.append('status', filters.status);
            if (filters.search) params.append('search', filters.search);
            params.append('limit', pagination.limit);
            params.append('offset', pagination.offset);
            
            const res = await fetch(`${API_BASE_URL}/api/gov/users?${params}`, {
                headers: { 'Authorization': `Bearer ${token}` }
            });
            if (res.ok) {
                const data = await res.json();
                setUsers(data.users || []);
                setPagination(prev => ({ ...prev, total: data.total }));
            }
        } catch (err) {
            console.error('Failed to fetch users:', err);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchCounts();
    }, []);

    useEffect(() => {
        fetchUsers();
    }, [filters, pagination.limit, pagination.offset]);

    const handleFilterChange = (key, value) => {
        setFilters(prev => ({ ...prev, [key]: value }));
        setPagination(prev => ({ ...prev, offset: 0 }));
    };

    const handleAction = async (userId, action) => {
        try {
            const res = await fetch(`${API_BASE_URL}/api/gov/users/${userId}/status`, {
                method: 'PATCH',
                headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
                body: JSON.stringify({ action, reason: actionReason })
            });
            if (res.ok) {
                fetchUsers();
                fetchCounts();
                setActionModal(null);
                setActionReason('');
            } else {
                const err = await res.json();
                alert(err.detail || 'Action failed');
            }
        } catch (err) {
            console.error('Action failed:', err);
        }
    };

    const formatDate = (dateStr) => {
        if (!dateStr) return '-';
        return new Date(dateStr).toLocaleDateString('en-PH', { 
            year: 'numeric', month: 'short', day: 'numeric',
            hour: '2-digit', minute: '2-digit'
        });
    };

    const residentActive = counts.resident?.active || 0;
    const residentSuspended = counts.resident?.suspended || 0;

    return (
        <div className="flex h-screen bg-slate-50 dark:bg-slate-950 overflow-hidden">
            <GovSidebar activeTab="residents" currentUser={currentUser} />
            
            <div className="flex-1 flex flex-col min-w-0 overflow-hidden">
                {/* Header */}
                <div className="bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800 p-4">
                <div className="flex items-center justify-between">
                    <div>
                        <h1 className="text-xl font-black text-slate-900 dark:text-white flex items-center gap-2">
                            <Users className="text-indigo-600" />
                            Resident Account Management
                        </h1>
                        <p className="text-sm text-slate-500 dark:text-slate-400">
                            View and manage resident citizen accounts
                        </p>
                    </div>
                    <div className="flex items-center gap-4">
                        <div className="flex gap-4 text-right">
                            <div>
                                <div className="text-2xl font-black text-emerald-600">{residentActive}</div>
                                <div className="text-xs text-slate-500 uppercase tracking-wider">Active</div>
                            </div>
                            <div>
                                <div className="text-2xl font-black text-red-500">{residentSuspended}</div>
                                <div className="text-xs text-slate-500 uppercase tracking-wider">Suspended</div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {workspace && <GovernmentWorkspaceTabs workspace={workspace} currentUser={currentUser} />}

            {/* Filters */}
            <div className="bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800 p-4">
                <div className="flex flex-wrap gap-3">
                    <div className="flex-1 min-w-[200px]">
                        <input
                            type="text"
                            placeholder="Search by name or email..."
                            value={filters.search}
                            onChange={(e) => handleFilterChange('search', e.target.value)}
                            className="w-full bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-700 rounded-xl px-4 py-2 text-sm font-medium outline-none focus:ring-2 focus:ring-indigo-500"
                        />
                    </div>
                    <select
                        value={filters.status}
                        onChange={(e) => handleFilterChange('status', e.target.value)}
                        className="bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-700 rounded-xl px-4 py-2 text-sm font-medium outline-none focus:ring-2 focus:ring-indigo-500"
                    >
                        <option value="">All Status</option>
                        <option value="active">Active</option>
                        <option value="suspended">Suspended</option>
                    </select>
                    <button 
                        onClick={fetchUsers}
                        className="px-4 py-2 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-xl text-sm font-bold flex items-center gap-2"
                    >
                        <RefreshCw size={16} />
                    </button>
                </div>
            </div>

            {/* User List */}
            <div className="flex-1 overflow-auto p-4">
                {loading ? (
                    <div className="flex items-center justify-center h-64">
                        <RefreshCw className="animate-spin text-indigo-600" size={32} />
                    </div>
                ) : users.length === 0 ? (
                    <div className="flex flex-col items-center justify-center h-64 text-slate-400">
                        <Users size={48} className="mb-4" />
                        <p className="font-bold">No residents found</p>
                    </div>
                ) : (
                    <div className="bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 overflow-hidden">
                        <table className="w-full">
                            <thead className="bg-slate-50 dark:bg-slate-950 border-b border-slate-200 dark:border-slate-800">
                                <tr>
                                    <th className="text-left text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider p-4">Resident</th>
                                    <th className="text-left text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider p-4">Barangay</th>
                                    <th className="text-left text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider p-4">Contact</th>
                                    <th className="text-left text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider p-4">Trust</th>
                                    <th className="text-left text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider p-4">Status</th>
                                    <th className="text-left text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider p-4">Joined</th>
                                    <th className="text-left text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider p-4">Actions</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                                {users.map((user, idx) => (
                                    <tr key={user.id || idx} className="hover:bg-slate-50 dark:hover:bg-slate-800/50">
                                        <td className="p-4">
                                            <div className="flex items-center gap-3">
                                                <div className="w-10 h-10 rounded-full bg-indigo-100 dark:bg-indigo-900/30 flex items-center justify-center text-indigo-600 dark:text-indigo-400 font-bold">
                                                    {user.full_name?.charAt(0).toUpperCase()}
                                                </div>
                                                <div>
                                                    <div className="text-sm font-bold text-slate-700 dark:text-slate-300">{user.full_name}</div>
                                                    <div className="text-xs text-slate-400">{user.email}</div>
                                                </div>
                                            </div>
                                        </td>
                                        <td className="p-4">
                                            <span className="text-sm text-slate-500 dark:text-slate-400">{user.barangay || '-'}</span>
                                        </td>
                                        <td className="p-4">
                                            <div className="text-xs text-slate-500 dark:text-slate-400">
                                                {user.phone_number && <div className="flex items-center gap-1"><Phone size={12} /> {user.phone_number}</div>}
                                            </div>
                                        </td>
                                        <td className="p-4">
                                            <span className={`text-sm font-bold ${user.trust_score >= 80 ? 'text-emerald-600' : user.trust_score >= 50 ? 'text-yellow-600' : 'text-red-600'}`}>
                                                {user.trust_score}%
                                            </span>
                                        </td>
                                        <td className="p-4">
                                            {user.is_suspended ? (
                                                <span className="text-xs font-bold text-red-600 bg-red-50 dark:bg-red-900/20 px-2 py-1 rounded-lg">
                                                    SUSPENDED
                                                </span>
                                            ) : user.is_active ? (
                                                <span className="text-xs font-bold text-emerald-600 bg-emerald-50 dark:bg-emerald-900/20 px-2 py-1 rounded-lg">
                                                    ACTIVE
                                                </span>
                                            ) : (
                                                <span className="text-xs font-bold text-slate-500 bg-slate-100 dark:bg-slate-800 px-2 py-1 rounded-lg">
                                                    INACTIVE
                                                </span>
                                            )}
                                        </td>
                                        <td className="p-4">
                                            <span className="text-xs text-slate-400">{formatDate(user.created_at)}</span>
                                        </td>
                                        <td className="p-4">
                                            <div className="flex gap-1">
                                                {user.is_suspended ? (
                                                    <button
                                                        onClick={() => handleAction(user.id, 'reactivate')}
                                                        className="p-2 text-emerald-600 hover:bg-emerald-50 dark:hover:bg-emerald-900/20 rounded-lg"
                                                        title="Reactivate"
                                                    >
                                                        <UserCheck size={16} />
                                                    </button>
                                                ) : user.is_active ? (
                                                    <button
                                                        onClick={() => { setSelectedUser(user); setActionModal('suspend'); }}
                                                        className="p-2 text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg"
                                                        title="Suspend"
                                                    >
                                                        <UserX size={16} />
                                                    </button>
                                                ) : (
                                                    <button
                                                        onClick={() => handleAction(user.id, 'activate')}
                                                        className="p-2 text-emerald-600 hover:bg-emerald-50 dark:hover:bg-emerald-900/20 rounded-lg"
                                                        title="Activate"
                                                    >
                                                        <UserCheck size={16} />
                                                    </button>
                                                )}
                                            </div>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}

                {/* Pagination */}
                {pagination.total > 0 && (
                    <div className="flex items-center justify-between mt-4 text-sm">
                        <div className="text-slate-500">
                            Showing {pagination.offset + 1} - {Math.min(pagination.offset + pagination.limit, pagination.total)} of {pagination.total}
                        </div>
                        <div className="flex gap-2">
                            <button
                                onClick={() => setPagination(prev => ({ ...prev, offset: Math.max(0, prev.offset - prev.limit) }))}
                                disabled={pagination.offset === 0}
                                className="px-3 py-1 bg-slate-100 dark:bg-slate-800 rounded-lg disabled:opacity-50"
                            >
                                Previous
                            </button>
                            <button
                                onClick={() => setPagination(prev => ({ ...prev, offset: prev.offset + prev.limit }))}
                                disabled={pagination.offset + pagination.limit >= pagination.total}
                                className="px-3 py-1 bg-slate-100 dark:bg-slate-800 rounded-lg disabled:opacity-50"
                            >
                                Next
                            </button>
                        </div>
                    </div>
                )}
            </div>

            {/* Action Modal */}
            {actionModal && selectedUser && (
                <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
                    <motion.div 
                        initial={{ opacity: 0 }} 
                        animate={{ opacity: 1 }} 
                        className="absolute inset-0 bg-slate-900/60" 
                        onClick={() => { setActionModal(null); setActionReason(''); }}
                    />
                    <motion.div
                        initial={{ opacity: 0, scale: 0.95, y: 20 }}
                        animate={{ opacity: 1, scale: 1, y: 0 }}
                        className="relative w-full max-w-md bg-white dark:bg-slate-900 rounded-2xl shadow-2xl border border-slate-200 dark:border-slate-800 p-6"
                    >
                        <h3 className="text-lg font-black text-slate-900 dark:text-white mb-2">
                            {actionModal === 'suspend' ? 'Suspend Resident' : 'Reactivate Resident'}
                        </h3>
                        <p className="text-sm text-slate-500 dark:text-slate-400 mb-4">
                            {actionModal === 'suspend' 
                                ? `Are you sure you want to suspend ${selectedUser.full_name}? They will lose access to the resident portal.`
                                : `Are you sure you want to reactivate ${selectedUser.full_name}?`
                            }
                        </p>
                        <textarea
                            placeholder="Reason (optional)"
                            value={actionReason}
                            onChange={(e) => setActionReason(e.target.value)}
                            className="w-full bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-700 rounded-xl px-4 py-2 text-sm font-medium outline-none focus:ring-2 focus:ring-indigo-500 mb-4"
                            rows={3}
                        />
                        <div className="flex gap-3">
                            <button 
                                onClick={() => { setActionModal(null); setActionReason(''); }}
                                className="flex-1 px-4 py-2 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-xl text-sm font-bold"
                            >
                                Cancel
                            </button>
                            <button 
                                onClick={() => handleAction(selectedUser.id, actionModal === 'suspend' ? 'suspend' : 'reactivate')}
                                className={`flex-1 px-4 py-2 rounded-xl text-sm font-bold ${
                                    actionModal === 'suspend'
                                    ? 'bg-red-600 hover:bg-red-700 text-white'
                                    : 'bg-emerald-600 hover:bg-emerald-700 text-white'
                                }`}
                            >
                                {actionModal === 'suspend' ? 'Suspend' : 'Reactivate'}
                            </button>
                        </div>
                    </motion.div>
                </div>
            )}
        </div>
    </div>
    );
}

